INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,8,'Al-Infitaar','فِيٓ أَيِّ صُورَةࣲ مَّا شَآءَ رَكَّبَكَ','اور جس صورت میں چاہا تجھے جوڑ دیا','moulding you in whatever form He willed','और जिस सूरत में उसने चाहा तेरे जोड़ बन्द मिलाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,9,'Al-Infitaar','كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ','مگر ہیہات تم لوگ جزا کو جھٹلاتے ہو','But no! In fact, you deny the ˹final˺ Judgment','हाँ बात ये है कि तुम लोग जज़ा (के दिन) को झुठलाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,10,'Al-Infitaar','وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ','حالانکہ تم پر نگہبان مقرر ہیں','while you are certainly observed by vigilant','हालॉकि तुम पर निगेहबान मुक़र्रर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,11,'Al-Infitaar','كِرَامࣰ ا كَٰتِبِينَ','عالی قدر (تمہاری باتوں کے) لکھنے والے','honourable angels, recording ˹everything˺','बुर्ज़ुग लोग (फरिश्ते सब बातों को) लिखने वाले (केरामन क़ातेबीन)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,12,'Al-Infitaar','يَعۡلَمُونَ مَا تَفۡعَلُونَ','جو تم کرتے ہو وہ اسے جانتے ہیں','They know whatever you do','जो कुछ तुम करते हो वह सब जानते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,13,'Al-Infitaar','إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمࣲ‏','بے شک نیکوکار نعمتوں (کی بہشت) میں ہوں گے۔','Indeed, the virtuous will be in bliss','बेशक नेको कार (बेहिश्त की) नेअमतों में होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,14,'Al-Infitaar','وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمࣲ‏','اور بدکردار دوزخ میں','and the wicked will be in Hell','और बदकार लोग यक़ीनन जहन्नुम में जज़ा के दिन');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,15,'Al-Infitaar','يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ','(یعنی) جزا کے دن اس میں داخل ہوں گے','burning in it on Judgment Day','उसी में झोंके जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,16,'Al-Infitaar','وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ','اور اس سے چھپ نہیں سکیں گے','and they will have no escape from it','और वह लोग उससे छुप न सकेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,17,'Al-Infitaar','وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ','اور تمہیں کیا معلوم کہ جزا کا دن کیسا ہے؟','What will make you realize what Judgment Day is','और तुम्हें क्या मालूम कि जज़ा का दिन क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,18,'Al-Infitaar','ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ','پھر تمہیں کیا معلوم کہ جزا کا دن کیسا ہے؟','Again, what will make you realize what Judgment Day is','फिर तुम्हें क्या मालूम कि जज़ा का दिन क्या चीज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (82,19,'Al-Infitaar','يَوۡمَ لَا تَمۡلِكُ نَفۡسࣱ لِّنَفۡسࣲ شَيۡـࣰٔ اۖ وَٱلۡأَمۡرُ يَوۡمَئِذࣲ لِّلَّهِ','جس روز کوئی کسی کا بھلا نہ کر سکے گا اور حکم اس روز خدا ہی کا ہو گا','˹It is˺ the Day no soul will be of ˹any˺ benefit to another whatsoever, for all authority on that Day belongs to Allah ˹entirely˺','उस दिन कोई शख़्श किसी शख़्श की भलाई न कर सकेगा और उस दिन हुक्म सिर्फ ख़ुदा ही का होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,1,'Al-Mutaffifin','وَيۡلࣱ لِّلۡمُطَفِّفِينَ','ناپ اور تول میں کمی کرنے والوں کے لیے خرابی ہے','Woe to the defrauders','नाप तौल में कमी करने वालों की ख़राबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,2,'Al-Mutaffifin','ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ','جو لوگوں سے ناپ کر لیں تو پورا لیں','Those who take full measure ˹when they buy˺ from people','जो औरें से नाप कर लें तो पूरा पूरा लें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,3,'Al-Mutaffifin','وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ','اور جب ان کو ناپ کر یا تول کر دیں تو کم کر دیں','but give less when they measure or weigh for buyers','और जब उनकी नाप या तौल कर दें तो कम कर दें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,4,'Al-Mutaffifin','أَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ','کیا یہ لوگ نہیں جانتے کہ اٹھائے بھی جائیں گے','Do such people not think that they will be resurrected','क्या ये लोग इतना भी ख्याल नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,5,'Al-Mutaffifin','لِيَوۡمٍ عَظِيمࣲ‏','(یعنی) ایک بڑے (سخت) دن میں','for a tremendous Day—','कि एक बड़े (सख्त) दिन (क़यामत) में उठाए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,6,'Al-Mutaffifin','يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ','جس دن (تمام) لوگ رب العالمین کے سامنے کھڑے ہوں گے','the Day ˹all˺ people will stand before the Lord of all worlds','जिस दिन तमाम लोग सारे जहाँन के परवरदिगार के सामने खड़े होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,7,'Al-Mutaffifin','كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينࣲ‏','سن رکھو کہ بدکارروں کے اعمال سجّین میں ہیں','But no! The wicked are certainly bound for Sijjîn ˹in the depths of Hell˺—','सुन रखो कि बदकारों के नाम ए अमाल सिज्जीन में हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,8,'Al-Mutaffifin','وَمَآ أَدۡرَىٰكَ مَا سِجِّينࣱ‏','اور تم کیا جانتے ہوں کہ سجّین کیا چیز ہے؟','and what will make you realize what Sijjîn is?—','तुमको क्या मालूम सिज्जीन क्या चीज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,9,'Al-Mutaffifin','كِتَٰبࣱ مَّرۡقُومࣱ‏','ایک دفتر ہے لکھا ہوا','a fate ˹already˺ sealed','एक लिखा हुआ दफ़तर है जिसमें शयातीन के (आमाल दर्ज हैं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,10,'Al-Mutaffifin','وَيۡلࣱ يَوۡمَئِذࣲ لِّلۡمُكَذِّبِينَ','اس دن جھٹلانے والوں کی خرابی ہے','Woe on that Day to the deniers—','उस दिन झुठलाने वालों की ख़राबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,11,'Al-Mutaffifin','ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ','(یعنی) جو انصاف کے دن کو جھٹلاتے ہیں','those who deny Judgment Day','जो लोग रोजे ज़ज़ा को झुठलाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,12,'Al-Mutaffifin','وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ','اور اس کو جھٹلاتا وہی ہے جو حد سے نکل جانے والا گنہگار ہے','None would deny it except every evildoing transgressor','हालॉकि उसको हद से निकल जाने वाले गुनाहगार के सिवा कोई नहीं झुठलाता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,13,'Al-Mutaffifin','إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ','جب اس کو ہماری آیتیں سنائی جاتی ہیں تو کہتا ہے کہ یہ تو اگلے لوگوں کے افسانے ہیں','Whenever Our revelations are recited to them, they say, “Ancient fables!”','जब उसके सामने हमारी आयतें पढ़ी जाती हैं तो कहता है कि ये तो अगलों के अफसाने हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,14,'Al-Mutaffifin','كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ','دیکھو یہ جو (اعمال بد) کرتے ہیں ان کا ان کے دلوں پر زنگ بیٹھ گیا ہے','But no! In fact, their hearts have been stained by all ˹the evil˺ they used to commit','नहीं नहीं बात ये है कि ये लोग जो आमाल (बद) करते हैं उनका उनके दिलों पर जंग बैठ गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,15,'Al-Mutaffifin','كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذࣲ لَّمَحۡجُوبُونَ','بےشک یہ لوگ اس روز اپنے پروردگار (کے دیدار) سے اوٹ میں ہوں گے','Undoubtedly, they will be sealed off from their Lord on that Day','बेशक ये लोग उस दिन अपने परवरदिगार (की रहमत से) रोक दिए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,16,'Al-Mutaffifin','ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ','پھر دوزخ میں جا داخل ہوں گے','Moreover, they will surely burn in Hell','फिर ये लोग ज़रूर जहन्नुम वासिल होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,17,'Al-Mutaffifin','ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ','پھر ان سے کہا جائے گا کہ یہ وہی چیز ہے جس کو تم جھٹلاتے تھے','and then be told, “This is what you used to deny.”','फिर उनसे कहा जाएगा कि ये वही चीज़ तो है जिसे तुम झुठलाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,18,'Al-Mutaffifin','كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ','(یہ بھی) سن رکھو کہ نیکوکاروں کے اعمال علیین میں ہیں','But no! The virtuous are certainly bound for ’Illiyûn ˹in elevated Gardens˺—','ये भी सुन रखो कि नेको के नाम ए अमाल इल्लीयीन में होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,19,'Al-Mutaffifin','وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ','اور تم کو کیا معلوم کہ علیین کیا چیز ہے؟','and what will make you realize what ’Illiyûn is?—','और तुमको क्या मालूम कि इल्लीयीन क्या है वह एक लिखा हुआ दफ़तर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,20,'Al-Mutaffifin','كِتَٰبࣱ مَّرۡقُومࣱ‏','ایک دفتر ہے لکھا ہوا','a fate ˹already˺ sealed','जिसमें नेकों के आमाल दर्ज हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,21,'Al-Mutaffifin','يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ','جس کے پاس مقرب (فرشتے) حاضر رہتے ہیں','witnessed by those nearest ˹to Allah˺','उसके पास मुक़र्रिब (फ़रिश्ते) हाज़िर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,22,'Al-Mutaffifin','إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ','بےشک نیک لوگ چین میں ہوں گے','Surely the virtuous will be in bliss','बेशक नेक लोग नेअमतों में होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,23,'Al-Mutaffifin','عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ','تختوں پر بیٹھے ہوئے نظارے کریں گے','˹seated˺ on ˹canopied˺ couches, gazing around','तख्तों पर बैठे नज़ारे करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,24,'Al-Mutaffifin','تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ','تم ان کے چہروں ہی سے راحت کی تازگی معلوم کر لو گے','You will recognize on their faces the glow of delight','तुम उनके चेहरों ही से राहत की ताज़गी मालूम कर लोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,25,'Al-Mutaffifin','يُسۡقَوۡنَ مِن رَّحِيقࣲ مَّخۡتُومٍ','ان کو خالص شراب سربمہر پلائی جائے گی','They will be given a drink of sealed, pure wine','उनको सर ब मोहर ख़ालिस शराब पिलायी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,26,'Al-Mutaffifin','خِتَٰمُهُۥ مِسۡكࣱۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ','جس کی مہر مشک کی ہو گی تو (نعمتوں کے) شائقین کو چاہیے کہ اسی سے رغبت کریں','whose last sip will smell like musk. So let whoever aspires to this strive ˹diligently˺','जिसकी मोहर मिश्क की होगी और उसकी तरफ अलबत्ता शायक़ीन को रग़बत करनी चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,27,'Al-Mutaffifin','وَمِزَاجُهُۥ مِن تَسۡنِيمٍ','اور اس میں تسنیم (کے پانی) کی آمیزش ہو گی','And this drink’s flavour will come from Tasnîm—','और उस (शराब) में तसनीम के पानी की आमेज़िश होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,28,'Al-Mutaffifin','عَيۡنࣰ ا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ','وہ ایک چشمہ ہے جس میں سے (خدا کے) مقرب پیئیں گے','a spring from which those nearest ˹to Allah˺ will drink','वह एक चश्मा है जिसमें मुक़रेबीन पियेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,29,'Al-Mutaffifin','إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ','جو گنہگار (یعنی کفار) ہیں وہ (دنیا میں) مومنوں سے ہنسی کیا کرتے تھے','Indeed, the wicked used to laugh at the believers','बेशक जो गुनाहगार मोमिनों से हँसी किया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,30,'Al-Mutaffifin','وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ','اور جب ان کے پاس سے گزرتے تو حقارت سے اشارے کرتے','wink to one another whenever they passed by','और जब उनके पास से गुज़रते तो उन पर चशमक करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,31,'Al-Mutaffifin','وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ','اور جب اپنے گھر کو لوٹتے تو اتراتے ہوئے لوٹتے','and muse ˹over these exploits˺ upon returning to their own people','और जब अपने लड़के वालों की तरफ़ लौट कर आते थे तो इतराते हुए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,32,'Al-Mutaffifin','وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ','اور جب ان (مومنوں) کو دیکھتے تو کہتے کہ یہ تو گمراہ ہیں','And when they saw the faithful, they would say, “These ˹people˺ are truly astray,”','और जब उन मोमिनीन को देखते तो कह बैठते थे कि ये तो यक़ीनी गुमराह हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,33,'Al-Mutaffifin','وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ','حالانکہ وہ ان پر نگراں بنا کر نہیں بھیجے گئے تھے','even though they were not sent as keepers over the believers','हालॉकि ये लोग उन पर कुछ निगराँ बना के तो भेजे नहीं गए थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,34,'Al-Mutaffifin','فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ','تو آج مومن کافروں سے ہنسی کریں گے','But on that Day the believers will be laughing at the disbelievers','तो आज (क़यामत में) ईमानदार लोग काफ़िरों से हँसी करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,35,'Al-Mutaffifin','عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ','(اور) تختوں پر (بیٹھے ہوئے ان کا حال) دیکھ رہے ہوں گے','as they sit on ˹canopied˺ couches, looking on','(और) तख्तों पर बैठे नज़ारे करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (83,36,'Al-Mutaffifin','هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ','تو کافروں کو ان کے عملوں کا (پورا پورا) بدلہ مل گیا','˹The believers will be asked,˺ “Have the disbelievers ˹not˺ been paid back for what they used to do?”','कि अब तो काफ़िरों को उनके किए का पूरा पूरा बदला मिल गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,1,'Al-Inshiqaaq','إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ','جب آسمان پھٹ جائے گا','When the sky bursts open','जब आसमान फट जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,2,'Al-Inshiqaaq','وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ','اور اپنے پروردگار کا فرمان بجا لائے گا اور اسے واجب بھی یہ ہی ہے','obeying its Lord as it must','और अपने परवरदिगार का हुक्म बजा लाएगा और उसे वाजिब भी यही है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,3,'Al-Inshiqaaq','وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ','اور جب زمین ہموار کر دی جائے گی','and when the earth is flattened out','और जब ज़मीन (बराबर करके) तान दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,4,'Al-Inshiqaaq','وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ','جو کچھ اس میں ہے اسے نکال کر باہر ڈال دے گی اور (بالکل) خالی ہو جائے گی','and ejects ˹all˺ its contents and becomes empty','और जो कुछ उसमें है उगल देगी और बिल्कुल ख़ाली हो जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,5,'Al-Inshiqaaq','وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ','اور اپنے پروردگار کے ارشاد کی تعمیل کرے گی اور اس کو لازم بھی یہی ہے (تو قیامت قائم ہو جائے گی)','obeying its Lord as it must, ˹surely you will all be judged˺','और अपने परवरदिगार का हुक्म बजा लाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,6,'Al-Inshiqaaq','يَٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحࣰ ا فَمُلَٰقِيهِ','اے انسان! تو اپنے پروردگار کی طرف (پہنچنے میں) خوب کوشِش کرتا ہے سو اس سے جا ملے گا','O humanity! Indeed, you are labouring restlessly towards your Lord, and will ˹eventually˺ meet the consequences','और उस पर लाज़िम भी यही है (तो क़यामत आ जाएगी) ऐ इन्सान तू अपने परवरदिगार की हुज़ूरी की कोशिश करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,7,'Al-Inshiqaaq','فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ','تو جس کا نامہٴ (اعمال) اس کے داہنے ہاتھ میں دیا جائے گا','As for those who are given their record in their right hand','तो तू (एक न एक दिन) उसके सामने हाज़िर होगा फिर (उस दिन) जिसका नामाए आमाल उसके दाहिने हाथ में दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,8,'Al-Inshiqaaq','فَسَوۡفَ يُحَاسَبُ حِسَابࣰ ا يَسِيرࣰ ا','اس سے حساب آسان لیا جائے گا','they will have an easy reckoning','उससे तो हिसाब आसान तरीके से लिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,9,'Al-Inshiqaaq','وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورࣰ ا','اور وہ اپنے گھر والوں میں خوش خوش آئے گا','and will return to their people joyfully','और (फिर) वह अपने (मोमिनीन के) क़बीले की तरफ ख़ुश ख़ुश पलटेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,10,'Al-Inshiqaaq','وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ','اور جس کا نامہٴ (اعمال) اس کی پیٹھ کے پیچھے سے دیا جائے گا','And as for those who are given their record ˹in their left hand˺ from behind their backs','लेकिन जिस शख़्श को उसका नामए आमल उसकी पीठ के पीछे से दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,11,'Al-Inshiqaaq','فَسَوۡفَ يَدۡعُواْ ثُبُورࣰ ا','وہ موت کو پکارے گا','they will cry for ˹instant˺ destruction','वह तो मौत की दुआ करेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,12,'Al-Inshiqaaq','وَيَصۡلَىٰ سَعِيرًا','اور وہ دوزخ میں داخل ہو گا','and will burn in the blazing Fire','और जहन्नुम वासिल होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,13,'Al-Inshiqaaq','إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا','یہ اپنے اہل (و عیال) میں مست رہتا تھا','For they used to be prideful among their people','ये शख़्श तो अपने लड़के बालों में मस्त रहता था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,14,'Al-Inshiqaaq','إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ','اور خیال کرتا تھا کہ (خدا کی طرف) پھر کر نہ جائے گا','thinking they would never return ˹to Allah˺','और समझता था कि कभी (ख़ुदा की तरफ) फिर कर जाएगा ही नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,15,'Al-Inshiqaaq','بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرࣰ ا','ہاں ہاں۔ اس کا پروردگار اس کو دیکھ رہا تھا','Yes ˹they would˺! Surely their Lord has always been All-Seeing of them','हाँ उसका परवरदिगार यक़ीनी उसको देख भाल कर रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,16,'Al-Inshiqaaq','فَلَآ أُقۡسِمُ بِٱلشَّفَقِ','ہمیں شام کی سرخی کی قسم','So, I do swear by the twilight','तो मुझे शाम की मुर्ख़ी की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,17,'Al-Inshiqaaq','وَٱلَّيۡلِ وَمَا وَسَقَ','اور رات کی اور جن چیزوں کو وہ اکٹھا کر لیتی ہے ان کی','And by the night and whatever it envelops','और रात की और उन चीज़ों की जिन्हें ये ढाँक लेती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,18,'Al-Inshiqaaq','وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ','اور چاند کی جب کامل ہو جائے','And by the moon when it waxes full','और चाँद की जब पूरा हो जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,19,'Al-Inshiqaaq','لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقࣲ‏','کہ تم درجہ بدرجہ (رتبہٴ اعلیٰ پر) چڑھو گے','You will certainly pass from one state to another','कि तुम लोग ज़रूर एक सख्ती के बाद दूसरी सख्ती में फँसोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,20,'Al-Inshiqaaq','فَمَا لَهُمۡ لَا يُؤۡمِنُونَ','تو ان لوگوں کو کیا ہوا ہے کہ ایمان نہیں لاتے','So what is the matter with them that they do not believe','तो उन लोगों को क्या हो गया है कि ईमान नहीं ईमान नहीं लाते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,21,'Al-Inshiqaaq','وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩','اور جب ان کے سامنے قرآن پڑھا جاتا ہے تو سجدہ نہیں کرتے','and when the Quran is recited to them, they do not bow down ˹in submission˺','और जब उनके सामने क़ुरान पढ़ा जाता है तो (ख़ुदा का) सजदा नहीं करते (21) (सजदा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,22,'Al-Inshiqaaq','بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ','بلکہ کافر جھٹلاتے ہیں','In fact, the disbelievers persist in denial','बल्कि काफ़िर लोग तो (और उसे) झुठलाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,23,'Al-Inshiqaaq','وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ','اور خدا ان باتوں کو جو یہ اپنے دلوں میں چھپاتے ہیں خوب جانتا ہے','But Allah knows best whatever they hide','और जो बातें ये लोग अपने दिलों में छिपाते हैं ख़ुदा उसे ख़ूब जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,24,'Al-Inshiqaaq','فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ','تو ان کو دکھ دینے والے عذاب کی خبر سنا دو','So give them good news of a painful punishment','तो (ऐ रसूल) उन्हें दर्दनाक अज़ाब की ख़ुशख़बरी दे दो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (84,25,'Al-Inshiqaaq','إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ','ہاں جو لوگ ایمان لائے اور نیک عمل کرتے رہے ان کے لیے بےانتہا اجر ہے','But those who believe and do good will have a never-ending reward','मगर जो लोग ईमान लाए और उन्होंने अच्छे अच्छे काम किए उनके लिए बेइन्तिहा अज्र (व सवाब है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,1,'Al-Burooj','وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ','آسمان کی قسم جس میں برج ہیں','By the sky full of constellations','बुर्ज़ों वाले आसमानों की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,2,'Al-Burooj','وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ','اور اس دن کی جس کا وعدہ ہے','and the promised Day ˹of Judgment˺','और उस दिन की जिसका वायदा किया गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,3,'Al-Burooj','وَشَاهِدࣲ وَمَشۡهُودࣲ‏','اور حاضر ہونے والے کی اور جو اس کے پاس حاضر کیا جائے اسکی','and the witness and what is witnessed','और गवाह की और जिसकी गवाही दे जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,4,'Al-Burooj','قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ','کہ خندقوں (کے کھودنے) والے ہلاک کر دیئے گئے','Condemned are the makers of the ditch—','उसकी (कि कुफ्फ़ार मक्का हलाक हुए) जिस तरह ख़न्दक़ वाले हलाक कर दिए गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,5,'Al-Burooj','ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ','(یعنی) آگ (کی خندقیں) جس میں ایندھن (جھونک رکھا) تھا','the fire ˹pit˺, filled with fuel—','जो ख़न्दक़ें आग की थीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,6,'Al-Burooj','إِذۡ هُمۡ عَلَيۡهَا قُعُودࣱ‏','جب کہ وہ ان (کے کناروں) پر بیٹھے ہوئے تھے','when they sat around it','जिसमें (उन्होंने मुसलमानों के लिए) ईंधन झोंक रखा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,7,'Al-Burooj','وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودࣱ‏','اور جو (سختیاں) اہل ایمان پر کر رہے تھے ان کو سامنے دیکھ رہے تھے','watching what they had ˹ordered to be˺ done to the believers','जब वह उन (ख़न्दक़ों) पर बैठे हुए और जो सुलूक ईमानदारों के साथ करते थे उसको सामने देख रहे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,8,'Al-Burooj','وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ','ان کو مومنوں کی یہی بات بری لگتی تھی کہ وہ خدا پر ایمان لائے ہوئے تھے جو غالب (اور) قابل ستائش ہے','who they resented for no reason other than belief in Allah—the Almighty, the Praiseworthy—','और उनको मोमिनीन की यही बात बुरी मालूम हुई कि वह लोग ख़ुदा पर ईमान लाए थे जो ज़बरदस्त और सज़ावार हम्द है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,9,'Al-Burooj','ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ','وہی جس کی آسمانوں اور زمین میں بادشاہت ہے۔ اور خدا ہر چیز سے واقف ہے','˹the One˺ to Whom belongs the kingdom of the heavens and earth. And Allah is a Witness over all things','वह (ख़ुदा) जिसकी सारे आसमान ज़मीन में बादशाहत है और ख़ुदा हर चीज़ से वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,10,'Al-Burooj','إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ','جن لوگوں نے مومن مردوں اور مومن عورتوں کو تکلیفیں دیں اور توبہ نہ کی ان کو دوزخ کا (اور) عذاب بھی ہوگا اور جلنے کا عذاب بھی ہوگا','Those who persecute the believing men and women and then do not repent will certainly suffer the punishment of Hell and the torment of burning','बेशक जिन लोगों ने ईमानदार मर्दों और औरतों को तकलीफें दीं फिर तौबा न की उनके लिए जहन्नुम का अज़ाब तो है ही (इसके अलावा) जलने का भी अज़ाब होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,11,'Al-Burooj','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتࣱ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ','(اور) جو لوگ ایمان لائے اور نیک کام کرتے رہے ان کے لیے باغات ہیں جن کے نیچے نہریں بہہ رہی ہیں۔ یہ ہی بڑی کامیابی ہے','Surely those who believe and do good will have Gardens under which rivers flow. That is the greatest triumph','बेशक जो लोग ईमान लाए और अच्छे काम करते रहे उनके लिए वह बाग़ात हैं जिनके नीचे नहरें जारी हैं यही तो बड़ी कामयाबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,12,'Al-Burooj','إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ','بےشک تمہارے پروردگار کی پکڑ بڑی سخت ہے','Indeed, the ˹crushing˺ grip of your Lord is severe','बेशक तुम्हारे परवरदिगार की पकड़ बहुत सख्त है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,13,'Al-Burooj','إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ','وہی پہلی دفعہ پیدا کرتا ہے اور وہی دوبارہ (زندہ) کرے گا','˹For˺ He is certainly the One Who originates and resurrects ˹all˺','वही पहली दफ़ा पैदा करता है और वही दोबारा (क़यामत में ज़िन्दा) करेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,14,'Al-Burooj','وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ','اور وہ بخشنے والا اور محبت کرنے والا ہے','And He is the All-Forgiving, All-Loving—','और वही बड़ा बख्शने वाला मोहब्बत करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,15,'Al-Burooj','ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ','عرش کا مالک بڑی شان والا','Lord of the Throne, the All-Glorious','अर्श का मालिक बड़ा आलीशान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,16,'Al-Burooj','فَعَّالࣱ لِّمَا يُرِيدُ','جو چاہتا ہے کر دیتا ہے','Doer of whatever He wills','जो चाहता है करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,17,'Al-Burooj','هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ','بھلا تم کو لشکروں کا حال معلوم ہوا ہے','Has the story of the ˹destroyed˺ forces reached you ˹O Prophet˺—','क्या तुम्हारे पास लशकरों की ख़बर पहुँची है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,18,'Al-Burooj','فِرۡعَوۡنَ وَثَمُودَ','(یعنی) فرعون اور ثمود کا','˹the forces of˺ Pharaoh and Thamûd','(यानि) फिरऔन व समूद की (ज़रूर पहुँची है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,19,'Al-Burooj','بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبࣲ‏','لیکن کافر (جان بوجھ کر) تکذیب میں (گرفتار) ہیں','Yet the disbelievers ˹still˺ persist in denial','मगर कुफ्फ़ार तो झुठलाने ही (की फ़िक्र) में हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,20,'Al-Burooj','وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ','اور خدا (بھی) ان کو گردا گرد سے گھیرے ہوئے ہے','But Allah encompasses them from all sides','और ख़ुदा उनको पीछे से घेरे हुए है (ये झुठलाने के क़ाबिल नहीं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,21,'Al-Burooj','بَلۡ هُوَ قُرۡءَانࣱ مَّجِيدࣱ‏','(یہ کتاب ہزل و بطلان نہیں) بلکہ یہ قرآن عظیم الشان ہے','In fact, this is a glorious Quran','बल्कि ये तो क़ुरान मजीद है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (85,22,'Al-Burooj','فِي لَوۡحࣲ مَّحۡفُوظِۭ','لوح محفوظ میں (لکھا ہوا)','˹recorded˺ in a Preserved Tablet','जो लौहे महफूज़ में लिखा हुआ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,1,'At-Taariq','وَٱلسَّمَآءِ وَٱلطَّارِقِ','آسمان اور رات کے وقت آنے والے کی قسم','By the heaven and the nightly star','आसमान और रात को आने वाले की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,2,'At-Taariq','وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ','اور تم کو کیا معلوم کہ رات کے وقت آنے والا کیا ہے','And what will make you realize what the nightly star is','और तुमको क्या मालूम रात को आने वाला क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,3,'At-Taariq','ٱلنَّجۡمُ ٱلثَّاقِبُ','وہ تارا ہے چمکنے والا','˹It is˺ the star of piercing brightness','(वह) चमकता हुआ तारा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,4,'At-Taariq','إِن كُلُّ نَفۡسࣲ لَّمَّا عَلَيۡهَا حَافِظࣱ‏','کہ کوئی متنفس نہیں جس پر نگہبان مقرر نہیں','There is no soul without a vigilant angel ˹recording everything˺','(इस बात की क़सम) कि कोई शख़्श ऐसा नहीं जिस पर निगेहबान मुक़र्रर नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,5,'At-Taariq','فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ','تو انسان کو دیکھنا چاہئے کہ وہ کاہے سے پیدا ہوا ہے','Let people then consider what they were created from','तो इन्सान को देखना चाहिए कि वह किस चीज़ से पैदा हुआ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,6,'At-Taariq','خُلِقَ مِن مَّآءࣲ دَافِقࣲ‏','وہ اچھلتے ہوئے پانی سے پیدا ہوا ہے','˹They were˺ created from a spurting fluid','वह उछलते हुए पानी (मनी) से पैदा हुआ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,7,'At-Taariq','يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ','جو پیٹھ اور سینے کے بیچ میں سے نکلتا ہے','stemming from between the backbone and the ribcage','जो पीठ और सीने की हड्डियों के बीच में से निकलता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,8,'At-Taariq','إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرࣱ‏','بےشک خدا اس کے اعادے (یعنی پھر پیدا کرنے) پر قادر ہے','Surely He is fully capable of bringing them back ˹to life˺','बेशक ख़ुदा उसके दोबारा (पैदा) करने पर ज़रूर कुदरत रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,9,'At-Taariq','يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ','جس دن دلوں کے بھید جانچے جائیں گے','on the Day all secrets will be disclosed','जिस दिन दिलों के भेद जाँचे जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,10,'At-Taariq','فَمَا لَهُۥ مِن قُوَّةࣲ وَلَا نَاصِرࣲ‏','تو انسان کی کچھ پیش نہ چل سکے گی اور نہ کوئی اس کا مددگار ہو گا','Then one will have neither power nor ˹any˺ helper','तो (उस दिन) उसका न कुछ ज़ोर चलेगा और न कोई मददगार होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,11,'At-Taariq','وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ','آسمان کی قسم جو مینہ برساتا ہے','By the sky with its recurring cycles','चक्कर (खाने) वाले आसमान की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,12,'At-Taariq','وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ','اور زمین کی قسم جو پھٹ جاتی ہے','and the earth with its sprouting plants','और फटने वाली (ज़मीन की क़सम)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,13,'At-Taariq','إِنَّهُۥ لَقَوۡلࣱ فَصۡلࣱ‏','کہ یہ کلام (حق کو باطل سے) جدا کرنے والا ہے','Surely this ˹Quran˺ is a decisive word','बेशक ये क़ुरान क़ौले फ़ैसल है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,14,'At-Taariq','وَمَا هُوَ بِٱلۡهَزۡلِ','اور بیہودہ بات نہیں ہے','and is not to be taken lightly','और लग़ो नहीं है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,15,'At-Taariq','إِنَّهُمۡ يَكِيدُونَ كَيۡدࣰ ا','یہ لوگ تو اپنی تدبیروں میں لگ رہے ہیں','They are certainly devising ˹evil˺ plans','बेशक ये कुफ्फ़ार अपनी तदबीर कर रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,16,'At-Taariq','وَأَكِيدُ كَيۡدࣰ ا','اور ہم اپنی تدبیر کر رہے ہیں','but I too am planning','और मैं अपनी तद्बीर कर रहा हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (86,17,'At-Taariq','فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا','تو تم کافروں کو مہلت دو بس چند روز ہی مہلت دو','So bear with the disbelievers ˹O Prophet˺. Let them be for ˹just˺ a little while','तो काफ़िरों को मोहलत दो बस उनको थोड़ी सी मोहलत दो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,1,'Al-A''laa','سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى','(اے پیغمبر) اپنے پروردگار جلیل الشان کے نام کی تسبیح کرو','Glorify the Name of your Lord, the Most High','ऐ रसूल अपने आलीशान परवरदिगार के नाम की तस्बीह करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,2,'Al-A''laa','ٱلَّذِي خَلَقَ فَسَوَّىٰ','جس نے (انسان کو) بنایا پھر (اس کے اعضاء کو) درست کیا','Who created and ˹perfectly˺ fashioned ˹all˺','जिसने (हर चीज़ को) पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,3,'Al-A''laa','وَٱلَّذِي قَدَّرَ فَهَدَىٰ','اور جس نے (اس کا) اندازہ ٹہرایا (پھر اس کو) رستہ بتایا','and Who ordained precisely and inspired accordingly','और दुरूस्त किया और जिसने (उसका) अन्दाज़ा मुक़र्रर किया फिर राह बतायी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,4,'Al-A''laa','وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ','اور جس نے چارہ اگایا','and Who brings forth ˹green˺ pasture','और जिसने (हैवानात के लिए) चारा उगाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,5,'Al-A''laa','فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ','پھر اس کو سیاہ رنگ کا کوڑا کر دیا','then reduces it to withered chaff','फिर ख़ुश्क उसे सियाह रंग का कूड़ा कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,6,'Al-A''laa','سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ','ہم تمہیں پڑھا دیں گے کہ تم فراموش نہ کرو گے','We will have you recite ˹the Quran, O Prophet,˺ so you will not forget ˹any of it˺','हम तुम्हें (ऐसा) पढ़ा देंगे कि कभी भूलो ही नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,7,'Al-A''laa','إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ','مگر جو خدا چاہے۔ وہ کھلی بات کو بھی جانتا ہے اور چھپی کو بھی','unless Allah wills otherwise. He surely knows what is open and what is hidden','मगर जो ख़ुदा चाहे (मन्सूख़ कर दे) बेशक वह खुली बात को भी जानता है और छुपे हुए को भी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,8,'Al-A''laa','وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ','ہم تم کو آسان طریقے کی توفیق دیں گے','We will facilitate for you the Way of Ease','और हम तुमको आसान तरीके की तौफ़ीक़ देंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,9,'Al-A''laa','فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ','سو جہاں تک نصیحت (کے) نافع (ہونے کی امید) ہو نصیحت کرتے رہو','So ˹always˺ remind ˹with the Quran˺—˹even˺ if the reminder is beneficial ˹only to some˺','तो जहाँ तक समझाना मुफ़ीद हो समझते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,10,'Al-A''laa','سَيَذَّكَّرُ مَن يَخۡشَىٰ','جو خوف رکھتا ہے وہ تو نصیحت پکڑے گا','Those in awe ˹of Allah˺ will be mindful ˹of it˺','जो खौफ रखता हो वह तो फौरी समझ जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,11,'Al-A''laa','وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى','اور (بےخوف) بدبخت پہلو تہی کرے گا','But it will be shunned by the most wretched','और बदबख्त उससे पहलू तही करेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,12,'Al-A''laa','ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ','جو (قیامت کو) بڑی (تیز) آگ میں داخل ہو گا','who will burn in the greatest Fire','जो (क़यामत में) बड़ी (तेज़) आग में दाख़िल होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,13,'Al-A''laa','ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ','پھر وہاں نہ مرے گا اور نہ جئے گا','where they will not ˹be able to˺ live or die','फिर न वहाँ मरेगा ही न जीयेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,14,'Al-A''laa','قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ','بے شک وہ مراد کو پہنچ گیا جو پاک ہوا','Successful indeed are those who purify themselves','वह यक़ीनन मुराद दिली को पहुँचा जो (शिर्क से) पाक हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,15,'Al-A''laa','وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ','اور اپنے پروردگار کے نام کا ذکر کرتا رہا اور نماز پڑھتا رہا','remember the Name of their Lord, and pray','और अपने परवरदिगार का ज़िक्र करता और नमाज़ पढ़ता रहा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,16,'Al-A''laa','بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا','مگر تم لوگ تو دنیا کی زندگی کو اختیار کرتے ہو','But you ˹deniers only˺ prefer the life of this world','मगर तुम लोग दुनियावी ज़िन्दगी को तरजीह देते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,17,'Al-A''laa','وَٱلۡأٓخِرَةُ خَيۡرࣱ وَأَبۡقَىٰٓ','حالانکہ آخرت بہت بہتر اور پائندہ تر ہے','even though the Hereafter is far better and more lasting','हालॉकि आख़ोरत कहीं बेहतर और देर पा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,18,'Al-A''laa','إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ','یہ بات پہلے صحیفوں میں (مرقوم) ہے','This is certainly ˹mentioned˺ in the earlier Scriptures—','बेशक यही बात अगले सहीफ़ों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (87,19,'Al-A''laa','صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ','(یعنی) ابراہیم اور موسیٰ کے صحیفوں میں','the Scriptures of Abraham and Moses','इबराहीम और मूसा के सहीफ़ों में भी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,1,'Al-Ghaashiya','هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ','بھلا تم کو ڈھانپ لینے والی (یعنی قیامت کا) حال معلوم ہوا ہے','Has the news of the Overwhelming Event reached you ˹O Prophet˺','भला तुमको ढाँप लेने वाली मुसीबत (क़यामत) का हाल मालुम हुआ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,2,'Al-Ghaashiya','وُجُوهࣱ يَوۡمَئِذٍ خَٰشِعَةٌ','اس روز بہت سے منہ (والے) ذلیل ہوں گے','On that Day ˹some˺ faces will be downcast','उस दिन बहुत से चेहरे ज़लील रूसवा होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,3,'Al-Ghaashiya','عَامِلَةࣱ نَّاصِبَةࣱ‏','سخت محنت کرنے والے تھکے ماندے','˹totally˺ overburdened, exhausted','(तौक़ व जंज़ीर से) मयक्क़त करने वाले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,4,'Al-Ghaashiya','تَصۡلَىٰ نَارًا حَامِيَةࣰ‏','دہکتی آگ میں داخل ہوں گے','burning in a scorching Fire','थके माँदे दहकती हुई आग में दाखिल होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,5,'Al-Ghaashiya','تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةࣲ‏','ایک کھولتے ہوئے چشمے کا ان کو پانی پلایا جائے گا','left to drink from a scalding spring','उन्हें एक खौलते हुए चशमें का पानी पिलाया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,6,'Al-Ghaashiya','لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعࣲ‏','اور خار دار جھاڑ کے سوا ان کے لیے کوئی کھانا نہیں (ہو گا)','They will have no food except a foul, thorny shrub','ख़ारदार झाड़ी के सिवा उनके लिए कोई खाना नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,7,'Al-Ghaashiya','لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعࣲ‏','جو نہ فربہی لائے اور نہ بھوک میں کچھ کام آئے','neither nourishing nor satisfying hunger','जो मोटाई पैदा करे न भूख में कुछ काम आएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,8,'Al-Ghaashiya','وُجُوهࣱ يَوۡمَئِذࣲ نَّاعِمَةࣱ‏','اور بہت سے منہ (والے) اس روز شادماں ہوں گے','On that Day ˹other˺ faces will be glowing with bliss','(और) बहुत से चेहरे उस दिन तरो ताज़ा होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,9,'Al-Ghaashiya','لِّسَعۡيِهَا رَاضِيَةࣱ‏','اپنے اعمال (کی جزا) سے خوش دل','˹fully˺ pleased with their striving','अपनी कोशिश (के नतीजे) पर शादमान');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,10,'Al-Ghaashiya','فِي جَنَّةٍ عَالِيَةࣲ‏','بہشت بریں میں','in an elevated Garden','एक आलीशान बाग़ में');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,11,'Al-Ghaashiya','لَّا تَسۡمَعُ فِيهَا لَٰغِيَةࣰ‏','وہاں کسی طرح کی بکواس نہیں سنیں گے','where no idle talk will be heard','वहाँ कोई लग़ो बात सुनेंगे ही नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,12,'Al-Ghaashiya','فِيهَا عَيۡنࣱ جَارِيَةࣱ‏','اس میں چشمے بہ رہے ہوں گے','In it will be a running spring','उसमें चश्में जारी होंगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,13,'Al-Ghaashiya','فِيهَا سُرُرࣱ مَّرۡفُوعَةࣱ‏','وہاں تخت ہوں گے اونچے بچھے ہوئے','along with thrones raised high','उसमें ऊँचे ऊँचे तख्त बिछे होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,14,'Al-Ghaashiya','وَأَكۡوَابࣱ مَّوۡضُوعَةࣱ‏','اور آبخورے (قرینے سے) رکھے ہوئے','and cups set at hand','और (उनके किनारे) गिलास रखे होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,15,'Al-Ghaashiya','وَنَمَارِقُ مَصۡفُوفَةࣱ‏','اور گاؤ تکیے قطار کی قطار لگے ہوئے','and ˹fine˺ cushions lined up','और गाँव तकिए क़तार की क़तार लगे होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,16,'Al-Ghaashiya','وَزَرَابِيُّ مَبۡثُوثَةٌ','اور نفیس مسندیں بچھی ہوئی','and ˹splendid˺ carpets spread out','और नफ़ीस मसनदे बिछी हुई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,17,'Al-Ghaashiya','أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ','یہ لوگ اونٹوں کی طرف نہیں دیکھتے کہ کیسے (عجیب) پیدا کیے گئے ہیں','Do they not ever reflect on camels—how they were ˹masterfully˺ created','तो क्या ये लोग ऊँट की तरह ग़ौर नहीं करते कि कैसा अजीब पैदा किया गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,18,'Al-Ghaashiya','وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ','اور آسمان کی طرف کہ کیسا بلند کیا گیا ہے','and the sky—how it was raised ˹high˺','और आसमान की तरफ कि क्या बुलन्द बनाया गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,19,'Al-Ghaashiya','وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ','اور پہاڑوں کی طرف کہ کس طرح کھڑے کیے گئے ہیں','and the mountains—how they were firmly set up','और पहाड़ों की तरफ़ कि किस तरह खड़े किए गए हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,20,'Al-Ghaashiya','وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ','اور زمین کی طرف کہ کس طرح بچھائی گئی','and the earth—how it was levelled out','और ज़मीन की तरफ कि किस तरह बिछायी गयी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,21,'Al-Ghaashiya','فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرࣱ‏','تو تم نصیحت کرتے رہو کہ تم نصیحت کرنے والے ہی ہو','So, ˹continue to˺ remind ˹all, O Prophet˺, for your duty is only to remind','तो तुम नसीहत करते रहो तुम तो बस नसीहत करने वाले हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,22,'Al-Ghaashiya','لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ','تم ان پر داروغہ نہیں ہو','You are not ˹there˺ to compel them ˹to believe˺','तुम कुछ उन पर दरोग़ा तो हो नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,23,'Al-Ghaashiya','إِلَّا مَن تَوَلَّىٰ وَكَفَرَ','ہاں جس نے منہ پھیرا اور نہ مانا','But whoever turns away, persisting in disbelief','हाँ जिसने मुँह फेर लिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,24,'Al-Ghaashiya','فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ','تو خدا اس کو بڑا عذاب دے گا','then Allah will inflict upon them the major punishment','और न माना तो ख़ुदा उसको बहुत बड़े अज़ाब की सज़ा देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,25,'Al-Ghaashiya','إِنَّ إِلَيۡنَآ إِيَابَهُمۡ','بےشک ان کو ہمارے پاس لوٹ کر آنا ہے','Surely to Us is their return','बेशक उनको हमारी तरफ़ लौट कर आना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (88,26,'Al-Ghaashiya','ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم','پھر ہم ہی کو ان سے حساب لینا ہے','then surely with Us is their reckoning','फिर उनका हिसाब हमारे ज़िम्मे है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,1,'Al-Fajr','وَٱلۡفَجۡرِ','فجر کی قسم','By the dawn','सुबह की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,2,'Al-Fajr','وَلَيَالٍ عَشۡرࣲ‏','اور دس راتوں کی','and the ten nights','और दस रातों की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,3,'Al-Fajr','وَٱلشَّفۡعِ وَٱلۡوَتۡرِ','اور جفت اور طاق کی','and the even and the odd','और ज़ुफ्त व ताक़ की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,4,'Al-Fajr','وَٱلَّيۡلِ إِذَا يَسۡرِ','اور رات کی جب جانے لگے','and the night when it passes','और रात की जब आने लगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,5,'Al-Fajr','هَلۡ فِي ذَٰلِكَ قَسَمࣱ لِّذِي حِجۡرٍ','اور بے شک یہ چیزیں عقلمندوں کے نزدیک قسم کھانے کے لائق ہیں کہ (کافروں کو ضرور عذاب ہو گا)','Is all this ˹not˺ a sufficient oath for those who have sense','अक्लमन्द के वास्ते तो ज़रूर बड़ी क़सम है (कि कुफ्फ़ार पर ज़रूर अज़ाब होगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,6,'Al-Fajr','أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ','کیا تم نے نہیں دیکھا کہ تمہارے پروردگار نے عاد کے ساتھ کیا کیا','Did you not see how your Lord dealt with ’Ȃd—','क्या तुमने देखा नहीं कि तुम्हारे आद के साथ क्या किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,7,'Al-Fajr','إِرَمَ ذَاتِ ٱلۡعِمَادِ','(جو) ارم (کہلاتے تھے اتنے) دراز قد','˹the people˺ of Iram—with ˹their˺ great stature','यानि इरम वाले दराज़ क़द');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,8,'Al-Fajr','ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ','کہ تمام ملک میں ایسے پیدا نہیں ہوئے تھے','unmatched in any other land','जिनका मिसल तमाम (दुनिया के) शहरों में कोई पैदा ही नहीं किया गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,9,'Al-Fajr','وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ','اور ثمود کے ساتھ (کیا کیا) جو وادئِ (قریٰ) میں پتھر تراشتے تھے (اور گھر بناتے) تھے','and Thamûd who carved ˹their homes into˺ the rocks in the ˹Stone˺ Valley','और समूद के साथ (क्या किया) जो वादी (क़रा) में पत्थर तराश कर घर बनाते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,10,'Al-Fajr','وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ','اور فرعون کے ساتھ (کیا کیا) جو خیمے اور میخیں رکھتا تھا','and the Pharaoh of mighty structures','और फिरऔन के साथ (क्या किया) जो (सज़ा के लिए) मेख़े रखता था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,11,'Al-Fajr','ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ','یہ لوگ ملکوں میں سرکش ہو رہے تھے','They all transgressed throughout the land','ये लोग मुख़तलिफ़ शहरों में सरकश हो रहे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,12,'Al-Fajr','فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ','اور ان میں بہت سی خرابیاں کرتے تھے','spreading much corruption there','और उनमें बहुत से फ़साद फैला रखे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,13,'Al-Fajr','فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ','تو تمہارے پروردگار نے ان پر عذاب کا کوڑا نازل کیا','So your Lord unleashed on them a scourge of punishment','तो तुम्हारे परवरदिगार ने उन पर अज़ाब का कोड़ा लगाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,14,'Al-Fajr','إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ','بے شک تمہارا پروردگار تاک میں ہے','˹For˺ your Lord is truly vigilant','बेशक तुम्हारा परवरदिगार ताक में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,15,'Al-Fajr','فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ','مگر انسان (عجیب مخلوق ہے کہ) جب اس کا پروردگار اس کو آزماتا ہے تو اسے عزت دیتا اور نعمت بخشتا ہے۔ تو کہتا ہے کہ (آہا) میرے پروردگار نے مجھے عزت بخشی','Now, whenever a human being is tested by their Lord through ˹His˺ generosity and blessings, they boast, “My Lord has ˹deservedly˺ honoured me!”','लेकिन इन्सान जब उसको उसका परवरदिगार (इस तरह) आज़माता है कि उसको इज्ज़त व नेअमत देता है, तो कहता है कि मेरे परवरदिगार ने मुझे इज्ज़त दी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,16,'Al-Fajr','وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ','اور جب (دوسری طرح) آزماتا ہے کہ اس پر روزی تنگ کر دیتا ہے تو کہتا ہے کہ (ہائے) میرے پروردگار نے مجھے ذلیل کیا','But when He tests them by limiting their provision, they protest, “My Lord has ˹undeservedly˺ humiliated me!”','मगर जब उसको (इस तरह) आज़माता है कि उस पर रोज़ी को तंग कर देता है बोल उठता है कि मेरे परवरदिगार ने मुझे ज़लील किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,17,'Al-Fajr','كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ','نہیں بلکہ تم لوگ یتیم کی خاطر نہیں کرتے','Absolutely not! In fact, you are not ˹even˺ gracious to the orphan','हरगिज़ नहीं बल्कि तुम लोग न यतीम की ख़ातिरदारी करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,18,'Al-Fajr','وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ','اور نہ مسکین کو کھانا کھلانے کی ترغیب دیتے ہو','nor do you urge one another to feed the poor','और न मोहताज को खाना खिलाने की तरग़ीब देते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,19,'Al-Fajr','وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلࣰ ا لَّمࣰّ ا','اور میراث کے مال سمیٹ کر کھا جاتے ہو','And you devour ˹others’˺ inheritance greedily','और मीरारा के माल (हलाल व हराम) को समेट कर चख जाते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,20,'Al-Fajr','وَتُحِبُّونَ ٱلۡمَالَ حُبࣰّ ا جَمࣰّ ا','اور مال کو بہت ہی عزیز رکھتے ہو','and love wealth fervently','और माल को बहुत ही अज़ीज़ रखते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,21,'Al-Fajr','كَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكࣰّ ا دَكࣰّ ا','تو جب زمین کی بلندی کوٹ کوٹ کو پست کر دی جائے گی','Enough! When the earth is entirely crushed over and over','सुन रखो कि जब ज़मीन कूट कूट कर रेज़ा रेज़ा कर दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,22,'Al-Fajr','وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفࣰّ ا صَفࣰّ ا','اور تمہارا پروردگار (جلوہ فرما ہو گا) اور فرشتے قطار باندھ باندھ کر آ موجود ہوں گے','and your Lord comes ˹to judge˺ with angels, rank upon rank','और तुम्हारे परवरदिगार का हुक्म और फ़रिश्ते कतार के कतार आ जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,23,'Al-Fajr','وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذࣲ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ','اور دوزخ اس دن حاضر کی جائے گی تو انسان اس دن متنبہ ہو گا مگر تنبہ (سے) اسے (فائدہ) کہاں (مل سکے گا)','and Hell is brought forth on that Day—this is when every ˹disbelieving˺ person will remember ˹their own sins˺. But what is the use of remembering then','और उस दिन जहन्नुम सामने कर दी जाएगी उस दिन इन्सान चौंकेगा मगर अब चौंकना कहाँ (फ़ायदा देगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,24,'Al-Fajr','يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي','کہے گا کاش میں نے اپنی زندگی (جاودانی کے لیے) کچھ آگے بھیجا ہوتا','They will cry, “I wish I had sent forth ˹something good˺ for my ˹true˺ life.”','(उस वक्त) क़हेगा कि काश मैने अपनी (इस) ज़िन्दगी के वास्ते कुछ पहले भेजा होता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,25,'Al-Fajr','فَيَوۡمَئِذࣲ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدࣱ‏','تو اس دن نہ کوئی خدا کے عذاب کی طرح کا (کسی کو) عذاب دے گا','On that Day He will punish ˹them˺ severely, like no other','तो उस दिन ख़ुदा ऐसा अज़ाब करेगा कि किसी ने वैसा अज़ाब न किया होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,26,'Al-Fajr','وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدࣱ‏','اور نہ کوئی ویسا جکڑنا جکڑے گا','and bind ˹them˺ tightly, like no other','और न कोई उसके जकड़ने की तरह जकड़ेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,27,'Al-Fajr','يَٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ','اے اطمینان پانے والی روح','˹Allah will say to the righteous,˺ “O tranquil soul','(और कुछ लोगों से कहेगा) ऐ इत्मेनान पाने वाली जान');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,28,'Al-Fajr','ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةࣰ مَّرۡضِيَّةࣰ‏','اپنے پروردگار کی طرف لوٹ چل۔ تو اس سے راضی وہ تجھ سے راضی','Return to your Lord, well pleased ˹with Him˺ and well pleasing ˹to Him˺','अपने परवरदिगार की तरफ़ चल तू उससे ख़ुश वह तुझ से राज़ी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,29,'Al-Fajr','فَٱدۡخُلِي فِي عِبَٰدِي','تو میرے (ممتاز) بندوں میں شامل ہو جا','So join My servants','तो मेरे (ख़ास) बन्दों में शामिल हो जा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (89,30,'Al-Fajr','وَٱدۡخُلِي جَنَّتِي','اور میری بہشت میں داخل ہو جا','and enter My Paradise.”','और मेरे बेहिश्त में दाख़िल हो जा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,1,'Al-Balad','لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ','ہمیں اس شہر (مکہ) کی قسم','I do swear by this city ˹of Mecca˺—','मुझे इस शहर (मक्का) की कसम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,2,'Al-Balad','وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ','اور تم اسی شہر میں تو رہتے ہو','even though you ˹O Prophet˺ are subject to abuse in this city—','और तुम इसी शहर में तो रहते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,3,'Al-Balad','وَوَالِدࣲ وَمَا وَلَدَ','اور باپ (یعنی آدم) اور اس کی اولاد کی قسم','and by every parent and ˹their˺ child','और (तुम्हारे) बाप (आदम) और उसकी औलाद की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,4,'Al-Balad','لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ','کہ ہم نے انسان کو تکلیف (کی حالت) میں (رہنے والا) بنایا ہے','Indeed, We have created humankind in ˹constant˺ struggle','हमने इन्सान को मशक्क़त में (रहने वाला) पैदा किया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,5,'Al-Balad','أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدࣱ‏','کیا وہ خیال رکھتا ہے کہ اس پر کوئی قابو نہ پائے گا','Do they think that no one has power over them','क्या वह ये समझता है कि उस पर कोई काबू न पा सकेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,6,'Al-Balad','يَقُولُ أَهۡلَكۡتُ مَالࣰ ا لُّبَدًا','کہتا ہے کہ میں نے بہت سا مال برباد کیا','boasting, “I have wasted enormous wealth!”','वह कहता है कि मैने अलग़ारों माल उड़ा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,7,'Al-Balad','أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ','کیا اسے یہ گمان ہے کہ اس کو کسی نے دیکھا نہیں','Do they think that no one sees them','क्या वह ये ख्याल रखता है कि उसको किसी ने देखा ही नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,8,'Al-Balad','أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ','بھلا ہم نےاس کو دو آنکھیں نہیں دیں؟','Have We not given them two eyes','क्या हमने उसे दोनों ऑंखें और ज़बान');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,9,'Al-Balad','وَلِسَانࣰ ا وَشَفَتَيۡنِ','اور زبان اور دو ہونٹ (نہیں دیئے)','a tongue, and two lips','और दोनों लब नहीं दिए (ज़रूर दिए)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,10,'Al-Balad','وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ','(یہ چیزیں بھی دیں) اور اس کو (خیر و شر کے) دونوں رستے بھی دکھا دیئے','and shown them the two ways ˹of right and wrong˺','और उसको (अच्छी बुरी) दोनों राहें भी दिखा दीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,11,'Al-Balad','فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ','مگر وہ گھاٹی پر سے ہو کر نہ گزرا','If only they had attempted the challenging path ˹of goodness instead˺','फिर वह घाटी पर से होकर (क्यों) नहीं गुज़रा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,12,'Al-Balad','وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ','اور تم کیا سمجھے کہ گھاٹی کیا ہے؟','And what will make you realize what ˹attempting˺ the challenging path is','और तुमको क्या मालूम कि घाटी क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,13,'Al-Balad','فَكُّ رَقَبَةٍ','کسی (کی) گردن کا چھڑانا','It is to free a slave','किसी (की) गर्दन का (गुलामी या कर्ज से) छुड़ाना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,14,'Al-Balad','أَوۡ إِطۡعَٰمࣱ فِي يَوۡمࣲ ذِي مَسۡغَبَةࣲ‏','یا بھوک کے دن کھانا کھلانا','or to give food in times of famine','या भूख के दिन रिश्तेदार यतीम या ख़ाकसार');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,15,'Al-Balad','يَتِيمࣰ ا ذَا مَقۡرَبَةٍ','یتیم رشتہ دار کو','to an orphaned relative','मोहताज को');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,16,'Al-Balad','أَوۡ مِسۡكِينࣰ ا ذَا مَتۡرَبَةࣲ‏','یا فقیر خاکسار کو','or to a poor person in distress','खाना खिलाना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,17,'Al-Balad','ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ','پھر ان لوگوں میں بھی (داخل) ہو جو ایمان لائے اور صبر کی نصیحت اور (لوگوں پر) شفقت کرنے کی وصیت کرتے رہے','and—above all—to be one of those who have faith and urge each other to perseverance and urge each other to compassion','फिर तो उन लोगों में (शामिल) हो जाता जो ईमान लाए और सब्र की नसीहत और तरस खाने की वसीयत करते रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,18,'Al-Balad','أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ','یہی لوگ صاحب سعادت ہیں','These are the people of the right','यही लोग ख़ुश नसीब हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,19,'Al-Balad','وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ','اور جنہوں نے ہماری آیتوں کو نہ مانا وہ بدبخت ہیں','As for those who deny Our signs, they are the people of the left','और जिन लोगों ने हमारी आयतों से इन्कार किया है यही लोग बदबख्त हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (90,20,'Al-Balad','عَلَيۡهِمۡ نَارࣱ مُّؤۡصَدَةُۢ','یہ لوگ آگ میں بند کر دیئے جائیں گے','The Fire will be sealed over them','कि उनको आग में डाल कर हर तरफ से बन्द कर दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,1,'Ash-Shams','وَٱلشَّمۡسِ وَضُحَىٰهَا','سورج کی قسم اور اس کی روشنی کی','By the sun and its brightness','सूरज की क़सम और उसकी रौशनी की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,2,'Ash-Shams','وَٱلۡقَمَرِ إِذَا تَلَىٰهَا','اور چاند کی جب اس کے پیچھے نکلے','and the moon as it follows it','और चाँद की जब उसके पीछे निकले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,3,'Ash-Shams','وَٱلنَّهَارِ إِذَا جَلَّىٰهَا','اور دن کی جب اُسے چمکا دے','and the day as it unveils it','और दिन की जब उसे चमका दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,4,'Ash-Shams','وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا','اور رات کی جب اُسے چھپا لے','and the night as it conceals it','और रात की जब उसे ढाँक ले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,5,'Ash-Shams','وَٱلسَّمَآءِ وَمَا بَنَىٰهَا','اور آسمان کی اور اس ذات کی جس نے اسے بنایا','And by heaven and ˹the One˺ Who built it','और आसमान की और जिसने उसे बनाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,6,'Ash-Shams','وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا','اور زمین کی اور اس کی جس نے اسے پھیلایا','and the earth and ˹the One˺ Who spread it','और ज़मीन की जिसने उसे बिछाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,7,'Ash-Shams','وَنَفۡسࣲ وَمَا سَوَّىٰهَا','اور انسان کی اور اس کی جس نے اس (کے اعضا) کو برابر کیا','And by the soul and ˹the One˺ Who fashioned it','और जान की और जिसने उसे दुरूस्त किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,8,'Ash-Shams','فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا','پھر اس کو بدکاری (سے بچنے) اور پرہیزگاری کرنے کی سمجھ دی','then with ˹the knowledge of˺ right and wrong inspired it','फिर उसकी बदकारी और परहेज़गारी को उसे समझा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,9,'Ash-Shams','قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا','کہ جس نے (اپنے) نفس (یعنی روح) کو پاک رکھا وہ مراد کو پہنچا','Successful indeed is the one who purifies their soul','(क़सम है) जिसने उस (जान) को (गनाह से) पाक रखा वह तो कामयाब हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,10,'Ash-Shams','وَقَدۡ خَابَ مَن دَسَّىٰهَا','اور جس نے اسے خاک میں ملایا وہ خسارے میں رہا','and doomed is the one who corrupts it','और जिसने उसे (गुनाह करके) दबा दिया वह नामुराद रहा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,11,'Ash-Shams','كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ','(قوم) ثمود نے اپنی سرکشی کے سبب (پیغمبر کو) جھٹلایا','Thamûd rejected ˹the truth˺ out of arrogance','क़ौम मसूद ने अपनी सरकशी से (सालेह पैग़म्बर को) झुठलाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,12,'Ash-Shams','إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا','جب ان میں سے ایک نہایت بدبخت اٹھا','when the most wicked of them was roused ˹to kill the she-camel˺','जब उनमें का एक बड़ा बदबख्त उठ खड़ा हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,13,'Ash-Shams','فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا','تو خدا کے پیغمبر (صالح) نے ان سے کہا کہ خدا کی اونٹنی اور اس کے پانی پینے کی باری سے عذر کرو','But the messenger of Allah warned them, “˹Do not disturb˺ Allah’s camel and her ˹turn to˺ drink!”','तो ख़ुदा के रसूल (सालेह) ने उनसे कहा कि ख़ुदा की ऊँटनी और उसके पानी पीने से तअर्रुज़ न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,14,'Ash-Shams','فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا','مگر انہوں نے پیغمبر کو جھٹلایا اور اونٹنی کی کونچیں کاٹ دیں تو خدا نے ان کےگناہ کے سبب ان پر عذاب نازل کیا اور سب کو (ہلاک کر کے) برابر کر دیا','Still they defied him and slaughtered her. So their Lord crushed them for their crime, levelling all to the ground','मगर उन लोगों पैग़म्बर को झुठलाया और उसकी कूँचे काट डाली तो ख़ुदा ने उनके गुनाहों सबब से उन पर अज़ाब नाज़िल किया फिर (हलाक करके) बराबर कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (91,15,'Ash-Shams','وَلَا يَخَافُ عُقۡبَٰهَا','اور اس کو ان کے بدلہ لینے کا کچھ بھی ڈر نہیں','He has no fear of consequences','और उसको उनके बदले का कोई ख़ौफ तो है नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,1,'Al-Lail','وَٱلَّيۡلِ إِذَا يَغۡشَىٰ','رات کی قسم جب (دن کو) چھپالے','By the night when it covers','रात की क़सम जब (सूरज को) छिपा ले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,2,'Al-Lail','وَٱلنَّهَارِ إِذَا تَجَلَّىٰ','اور دن کی قسم جب چمک اٹھے','and the day when it shines','और दिन की क़सम जब ख़ूब रौशन हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,3,'Al-Lail','وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ','اور اس (ذات) کی قسم جس نے نر اور مادہ پیدا کیے','And by ˹the One˺ Who created male and female','और उस (ज़ात) की जिसने नर व मादा को पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,4,'Al-Lail','إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ','کہ تم لوگوں کی کوششں طرح طرح کی ہے','Surely the ends you strive for are diverse','कि बेशक तुम्हारी कोशिश तरह तरह की है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,5,'Al-Lail','فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ','تو جس نے (خدا کے رستے میں مال) دیا اور پرہیز گاری کی','As for the one who is charitable, mindful ˹of Allah˺','तो जिसने सख़ावत की और अच्छी बात (इस्लाम) की तस्दीक़ की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,6,'Al-Lail','وَصَدَّقَ بِٱلۡحُسۡنَىٰ','اور نیک بات کو سچ جانا','and ˹firmly˺ believes in the finest reward','तो हम उसके लिए राहत व आसानी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,7,'Al-Lail','فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ','اس کو ہم آسان طریقے کی توفیق دیں گے','We will facilitate for them the Way of Ease','(जन्नत) के असबाब मुहय्या कर देंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,8,'Al-Lail','وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ','اور جس نے بخل کیا اور بےپروا بنا رہا','And as for the one who is stingy, indifferent ˹to Allah˺','और जिसने बुख्ल किया, और बेपरवाई की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,9,'Al-Lail','وَكَذَّبَ بِٱلۡحُسۡنَىٰ','اور نیک بات کو جھوٹ سمجھا','and ˹staunchly˺ denies the finest reward','और अच्छी बात को झुठलाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,10,'Al-Lail','فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ','اسے سختی میں پہنچائیں گے','We will facilitate for them the path of hardship','तो हम उसे सख्ती (जहन्नुम) में पहुँचा देंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,11,'Al-Lail','وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ','اور جب وہ (دوزخ کے گڑھے میں) گرے گا تو اس کا مال اس کے کچھ کام نہ آئے گا','And their wealth will be of no benefit to them when they tumble ˹into Hell˺','और जब वह हलाक होगा तो उसका माल उसके कुछ भी काम न आएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,12,'Al-Lail','إِنَّ عَلَيۡنَا لَلۡهُدَىٰ','ہمیں تو راہ دکھا دینا ہے','It is certainly upon Us ˹alone˺ to show ˹the way to˺ guidance','हमें राह दिखा देना ज़रूर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,13,'Al-Lail','وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ','اور آخرت او ردنیا ہماری ہی چیزیں ہیں','And surely to Us ˹alone˺ belong this life and the next','और आख़ेरत और दुनिया (दोनों) ख़ास हमारी चीज़े हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,14,'Al-Lail','فَأَنذَرۡتُكُمۡ نَارࣰ ا تَلَظَّىٰ','سو میں نے تم کو بھڑکتی آگ سے متنبہ کر دیا','And so I have warned you of a raging Fire','तो हमने तुम्हें भड़कती हुई आग से डरा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,15,'Al-Lail','لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى','اس میں وہی داخل ہو گا جو بڑا بدبخت ہے','in which none will burn except the most wretched—','उसमें बस वही दाख़िल होगा जो बड़ा बदबख्त है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,16,'Al-Lail','ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ','جس نے جھٹلایا اور منہ پھیرا','who deny and turn away','जिसने झुठलाया और मुँह फेर लिया और जो बड़ा परहेज़गार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,17,'Al-Lail','وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى','اور جو بڑا پرہیزگار ہے وہ (اس سے) بچا لیا جائے گا','But the righteous will be spared from it—','वह उससे बचा लिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,18,'Al-Lail','ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ','جو مال دیتا ہے تاکہ پاک ہو','who donate ˹some of˺ their wealth only to purify themselves','जो अपना माल (ख़ुदा की राह) में देता है ताकि पाक हो जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,19,'Al-Lail','وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةࣲ تُجۡزَىٰٓ','اور (اس لیے) نہیں (دیتا کہ) اس پر کسی کا احسان (ہے) جس کا وہ بدلہ اتارتا ہے','not in return for someone’s favours','और लुत्फ ये है कि किसी का उस पर कोई एहसान नहीं जिसका उसे बदला दिया जाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,20,'Al-Lail','إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ','بلکہ اپنے خداوند اعلیٰ کی رضامندی حاصل کرنے کے لیے دیتا ہے','but seeking the pleasure of their Lord, the Most High','बल्कि (वह तो) सिर्फ अपने आलीशान परवरदिगार की ख़ुशनूदी हासिल करने के लिए (देता है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (92,21,'Al-Lail','وَلَسَوۡفَ يَرۡضَىٰ','اور وہ عنقریب خوش ہو جائے گا','They will certainly be pleased','और वह अनक़रीब भी ख़ुश हो जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,1,'Ad-Dhuhaa','وَٱلضُّحَىٰ','آفتاب کی روشنی کی قسم','By the morning sunlight','(ऐ रसूल) पहर दिन चढ़े की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,2,'Ad-Dhuhaa','وَٱلَّيۡلِ إِذَا سَجَىٰ','اور رات (کی تاریکی) کی جب چھا جائے','and the night when it falls still','और रात की जब (चीज़ों को) छुपा ले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,3,'Ad-Dhuhaa','مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ','کہ (اے محمدﷺ) تمہارے پروردگار نے نہ تو تم کو چھوڑا اور نہ (تم سے) ناراض ہوا','Your Lord ˹O Prophet˺ has not abandoned you, nor has He become hateful ˹of you˺','कि तुम्हारा परवरदिगार न तुमको छोड़ बैठा और (न तुमसे) नाराज़ हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,4,'Ad-Dhuhaa','وَلَلۡأٓخِرَةُ خَيۡرࣱ لَّكَ مِنَ ٱلۡأُولَىٰ','اور آخرت تمہارے لیے پہلی (حالت یعنی دنیا) سے کہیں بہتر ہے','And the next life is certainly far better for you than this one','और तुम्हारे वास्ते आख़ेरत दुनिया से यक़ीनी कहीं बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,5,'Ad-Dhuhaa','وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ','اور تمہیں پروردگار عنقریب وہ کچھ عطا فرمائے گا کہ تم خوش ہو جاؤ گے','And ˹surely˺ your Lord will give so much to you that you will be pleased','और तुम्हारा परवरदिगार अनक़रीब इस क़दर अता करेगा कि तुम ख़ुश हो जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,6,'Ad-Dhuhaa','أَلَمۡ يَجِدۡكَ يَتِيمࣰ ا فَـَٔاوَىٰ','بھلا اس نے تمہیں یتیم پا کر جگہ نہیں دی؟ (بےشک دی)','Did He not find you as an orphan then sheltered you','क्या उसने तुम्हें यतीम पाकर (अबू तालिब की) पनाह न दी (ज़रूर दी)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,7,'Ad-Dhuhaa','وَوَجَدَكَ ضَآلࣰّ ا فَهَدَىٰ','اور رستے سے ناواقف دیکھا تو رستہ دکھایا','Did He not find you unguided then guided you','और तुमको एहकाम से नावाकिफ़ देखा तो मंज़िले मक़सूद तक पहुँचा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,8,'Ad-Dhuhaa','وَوَجَدَكَ عَآئِلࣰ ا فَأَغۡنَىٰ','اور تنگ دست پایا تو غنی کر دیا','And did He not find you needy then satisfied your needs','और तुमको तंगदस्त देखकर ग़नी कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,9,'Ad-Dhuhaa','فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ','تو تم بھی یتیم پر ستم نہ کرنا','So do not oppress the orphan','तो तुम भी यतीम पर सितम न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,10,'Ad-Dhuhaa','وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ','اور مانگنے والے کو جھڑکی نہ دینا','nor repulse the beggar','माँगने वाले को झिड़की न देना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (93,11,'Ad-Dhuhaa','وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ','اور اپنے پروردگار کی نعمتوں کا بیان کرتے رہنا','And proclaim the blessings of your Lord','और अपने परवरदिगार की नेअमतों का ज़िक्र करते रहना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,1,'Ash-Sharh','أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ','(اے محمدﷺ) کیا ہم نے تمہارا سینہ کھول نہیں دیا؟ (بےشک کھول دیا)','Have We not uplifted your heart for you ˹O Prophet˺','(ऐ रसूल) क्या हमने तुम्हारा सीना इल्म से कुशादा नहीं कर दिया (जरूर किया)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,2,'Ash-Sharh','وَوَضَعۡنَا عَنكَ وِزۡرَكَ','اور تم پر سے بوجھ بھی اتار دیا','relieved you of the burden','और तुम पर से वह बोझ उतार दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,3,'Ash-Sharh','ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ','جس نے تمہاری پیٹھ توڑ رکھی تھی','which weighed so heavily on your back','जिसने तुम्हारी कमर तोड़ रखी थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,4,'Ash-Sharh','وَرَفَعۡنَا لَكَ ذِكۡرَكَ','اور تمہارا ذکر بلند کیا','and elevated your renown for you','और तुम्हारा ज़िक्र भी बुलन्द कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,5,'Ash-Sharh','فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا','ہاں ہاں مشکل کے ساتھ آسانی بھی ہے','So, surely with hardship comes ease','तो (हाँ) पस बेशक दुशवारी के साथ ही आसानी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,6,'Ash-Sharh','إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرࣰ ا','(اور) بے شک مشکل کے ساتھ آسانی ہے','Surely with ˹that˺ hardship comes ˹more˺ ease','यक़ीनन दुश्वारी के साथ आसानी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,7,'Ash-Sharh','فَإِذَا فَرَغۡتَ فَٱنصَبۡ','تو جب فارغ ہوا کرو تو (عبادت میں) محنت کیا کرو','So once you have fulfilled ˹your duty˺, strive ˹in devotion˺','तो जब तुम फारिग़ हो जाओ तो मुक़र्रर कर दो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (94,8,'Ash-Sharh','وَإِلَىٰ رَبِّكَ فَٱرۡغَب','اور اپنے پروردگار کی طرف متوجہ ہو جایا کرو','turning to your Lord ˹alone˺ with hope','और फिर अपने परवरदिगार की तरफ रग़बत करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,1,'At-Tin','وَٱلتِّينِ وَٱلزَّيۡتُونِ','انجیر کی قسم اور زیتون کی','By the fig and the olive ˹of Jerusalem˺','इन्जीर और ज़ैतून की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,2,'At-Tin','وَطُورِ سِينِينَ','اور طور سینین کی','and Mount Sinai','और तूर सीनीन की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,3,'At-Tin','وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ','اور اس امن والے شہر کی','and this secure city ˹of Mecca˺','और उस अमन वाले शहर (मक्का) की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,4,'At-Tin','لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمࣲ‏','کہ ہم نے انسان کو بہت اچھی صورت میں پیدا کیا ہے','Indeed, We created humans in the best form','कि हमने इन्सान बहुत अच्छे कैड़े का पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,5,'At-Tin','ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ','پھر (رفتہ رفتہ) اس (کی حالت) کو (بدل کر) پست سے پست کر دیا','But We will reduce them to the lowest of the low ˹in Hell˺','फिर हमने उसे (बूढ़ा करके रफ्ता रफ्ता) पस्त से पस्त हालत की तरफ फेर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,6,'At-Tin','إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونࣲ‏','مگر جو لوگ ایمان لائے اور نیک عمل کرتے رہے انکے لیے بےانتہا اجر ہے','except those who believe and do good—they will have a never-ending reward','मगर जो लोग ईमान लाए और अच्छे (अच्छे) काम करते रहे उनके लिए तो बे इन्तेहा अज्र व सवाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,7,'At-Tin','فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ','تو (اے آدم زاد) پھر تو جزا کے دن کو کیوں جھٹلاتا ہے؟','Now, what makes you deny the ˹final˺ Judgment','तो (ऐ रसूल) इन दलीलों के बाद तुमको (रोज़े) जज़ा के बारे में कौन झुठला सकता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (95,8,'At-Tin','أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ','کیا خدا سب سے بڑا حاکم نہیں ہے؟','Is Allah not the most just of all judges','क्या ख़ुदा सबसे बड़ा हाकिम नहीं है (हाँ ज़रूर है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,1,'Al-Alaq','ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ','(اے محمدﷺ) اپنے پروردگار کا نام لے کر پڑھو جس نے (عالم کو) پیدا کیا','Read, ˹O Prophet,˺ in the Name of your Lord Who created—','(ऐ रसूल) अपने परवरदिगार का नाम लेकर पढ़ो जिसने हर (चीज़ को) पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,2,'Al-Alaq','خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ','جس نے انسان کو خون کی پھٹکی سے بنایا','created humans from a clinging clot','उस ने इन्सान को जमे हुए ख़ून से पैदा किया पढ़ो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,3,'Al-Alaq','ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ','پڑھو اور تمہارا پروردگار بڑا کریم ہے','Read! And your Lord is the Most Generous','और तुम्हारा परवरदिगार बड़ा क़रीम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,4,'Al-Alaq','ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ','جس نے قلم کے ذریعے سے علم سکھایا','Who taught by the pen—','जिसने क़लम के ज़रिए तालीम दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,5,'Al-Alaq','عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ','اور انسان کو وہ باتیں سکھائیں جس کا اس کو علم نہ تھا','taught humanity what they knew not','उसीने इन्सान को वह बातें बतायीं जिनको वह कुछ जानता ही न था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,6,'Al-Alaq','كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ','مگر انسان سرکش ہو جاتا ہے','Most certainly, one exceeds all bounds','सुन रखो बेशक इन्सान जो अपने को ग़नी देखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,7,'Al-Alaq','أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ','جب کہ اپنے تیئں غنی دیکھتا ہے','once they think they are self-sufficient','तो सरकश हो जाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,8,'Al-Alaq','إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ','کچھ شک نہیں کہ (اس کو) تمہارے پروردگار ہی کی طرف لوٹ کر جانا ہے','˹But˺ surely to your Lord is the return ˹of all˺','बेशक तुम्हारे परवरदिगार की तरफ (सबको) पलटना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,9,'Al-Alaq','أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ','بھلا تم نے اس شخص کو دیکھا جو منع کرتا ہے','Have you seen the man who prevents','भला तुमने उस शख़्श को भी देखा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,10,'Al-Alaq','عَبۡدًا إِذَا صَلَّىٰٓ','(یعنی) ایک بندے کو جب وہ نماز پڑھنے لگتا ہے','a servant ˹of Ours˺ from praying','जो एक बन्दे को जब वह नमाज़ पढ़ता है तो वह रोकता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,11,'Al-Alaq','أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ','بھلا دیکھو تو اگر یہ راہِ راست پر ہو','What if this ˹servant˺ is ˹rightly˺ guided','भला देखो तो कि अगर ये राहे रास्त पर हो या परहेज़गारी का हुक्म करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,12,'Al-Alaq','أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ','یا پرہیز گاری کا حکم کرے (تو منع کرنا کیسا)','or encourages righteousness','तो रोकना कैसा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,13,'Al-Alaq','أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ','اور دیکھو تو اگر اس نے دین حق کو جھٹلایا اور اس سے منہ موڑا (تو کیا ہوا)','What if that ˹man˺ persists in denial and turns away','भला देखो तो कि अगर उसने (सच्चे को) झुठला दिया और (उसने) मुँह फेरा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,14,'Al-Alaq','أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ','کیااس کو معلوم نہیں کہ خدا دیکھ رہا ہے','Does he not know that Allah sees ˹all˺','(तो नतीजा क्या होगा) क्या उसको ये मालूम नहीं कि ख़ुदा यक़ीनन देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,15,'Al-Alaq','كَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ','دیکھو اگر وہ باز نہ آئے گا تو ہم (اس کی) پیشانی کے بال پکڑ گھسیٹیں گے','But no! If he does not desist, We will certainly drag him by the forelock—','देखो अगर वह बाज़ न आएगा तो हम परेशानी के पट्टे पकड़ के घसीटेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,16,'Al-Alaq','نَاصِيَةࣲ كَٰذِبَةٍ خَاطِئَةࣲ‏','یعنی اس جھوٹے خطاکار کی پیشانی کے بال','a lying, sinful forelock','झूठे ख़तावार की पेशानी के पट्टे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,17,'Al-Alaq','فَلۡيَدۡعُ نَادِيَهُۥ','تو وہ اپنے یاروں کی مجلس کو بلالے','So let him call his associates','तो वह अपने याराने जलसा को बुलाए हम भी जल्लाद फ़रिश्ते को बुलाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,18,'Al-Alaq','سَنَدۡعُ ٱلزَّبَانِيَةَ','ہم بھی اپنے موکلانِ دوزخ کو بلا لیں گے','We will call the wardens of Hell','(ऐ रसूल) देखो हरगिज़ उनका कहना न मानना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (96,19,'Al-Alaq','كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩','دیکھو اس کا کہا نہ ماننا اور قربِ (خدا) حاصل کرتے رہنا','Again, no! Never obey him ˹O Prophet˺! Rather, ˹continue to˺ prostrate and draw near ˹to Allah˺','और सजदे करते रहो और कुर्ब हासिल करो (19) (सजदा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (97,1,'Al-Qadr','إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ','ہم نے اس (قرآن) کو شب قدر میں نازل (کرنا شروع) کیا','Indeed, ˹it is˺ We ˹Who˺ sent this ˹Quran˺ down on the Night of Glory','हमने (इस कुरान) को शबे क़द्र में नाज़िल (करना शुरू) किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (97,2,'Al-Qadr','وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ','اور تمہیں کیا معلوم کہ شب قدر کیا ہے؟','And what will make you realize what the Night of Glory is','और तुमको क्या मालूम शबे क़द्र क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (97,3,'Al-Qadr','لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرࣱ مِّنۡ أَلۡفِ شَهۡرࣲ‏','شب قدر ہزار مہینے سے بہتر ہے','The Night of Glory is better than a thousand months','शबे क़द्र (मरतबा और अमल में) हज़ार महीनो से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (97,4,'Al-Qadr','تَنَزَّلُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرࣲ‏','اس میں روح (الامین) اور فرشتے ہر کام کے (انتظام کے) لیے اپنے پروردگار کے حکم سے اترتے ہیں','That night the angels and the ˹holy˺ spirit descend, by the permission of their Lord, for every ˹decreed˺ matter','इस (रात) में फ़रिश्ते और जिबरील (साल भर की) हर बात का हुक्म लेकर अपने परवरदिगार के हुक्म से नाज़िल होते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (97,5,'Al-Qadr','سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ','یہ (رات) طلوع صبح تک (امان اور) سلامتی ہے','It is all peace until the break of dawn','ये रात सुबह के तुलूअ होने तक (अज़सरतापा) सलामती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,1,'Al-Bayyina','لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ','جو لوگ کافر ہیں (یعنی) اہل کتاب اور مشرک وہ (کفر سے) باز رہنے والے نہ تھے جب تک ان کے پاس کھلی دلیل (نہ) آتی','The disbelievers from the People of the Book and the polytheists were not going to desist ˹from disbelief˺ until the clear proof came to them','अहले किताब और मुशरिकों से जो लोग काफिर थे जब तक कि उनके पास खुली हुई दलीलें न पहुँचे वह (अपने कुफ्र से) बाज़ आने वाले न थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,2,'Al-Bayyina','رَسُولࣱ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفࣰ ا مُّطَهَّرَةࣰ‏','(یعنی) خدا کے پیغمبر جو پاک اوراق پڑھتے ہیں','a messenger from Allah, reciting scrolls of ˹utmost˺ purity','(यानि) ख़ुदा के रसूल जो पाक औराक़ पढ़ते हैं (आए और)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,3,'Al-Bayyina','فِيهَا كُتُبࣱ قَيِّمَةࣱ‏','جن میں (مستحکم) آیتیں لکھی ہوئی ہیں','containing upright commandments','उनमें (जो) पुरज़ोर और दरूस्त बातें लिखी हुई हैं (सुनाये)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,4,'Al-Bayyina','وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ','اور اہل کتاب جو متفرق (و مختلف) ہوئے ہیں تو دلیل واضح آنے کے بعد (ہوئے ہیں)','It was not until this clear proof came to the People of the Book that they became divided ˹about his prophethood˺—','अहले किताब मुताफ़र्रिक़ हुए भी तो जब उनके पास खुली हुई दलील आ चुकी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,5,'Al-Bayyina','وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ','اور ان کو حکم تو یہی ہوا تھا کہ اخلاص عمل کے ساتھ خدا کی عبادت کریں (اور) یکسو ہو کراورنماز پڑھیں اور زکوٰة دیں اور یہی سچا دین ہے','even though they were only commanded to worship Allah ˹alone˺ with sincere devotion to Him in all uprightness, establish prayer, and pay alms-tax. That is the upright Way','(तब) और उन्हें तो बस ये हुक्म दिया गया था कि निरा ख़ुरा उसी का एतक़ाद रख के बातिल से कतरा के ख़ुदा की इबादत करे और पाबन्दी से नमाज़ पढ़े और ज़कात अदा करता रहे और यही सच्चा दीन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,6,'Al-Bayyina','إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ','جو لوگ کافر ہیں (یعنی) اہل کتاب اور مشرک وہ دوزخ کی آگ میں پڑیں گے (اور) ہمیشہ اس میں رہیں گے۔ یہ لوگ سب مخلوق سے بدتر ہیں','Indeed, those who disbelieve from the People of the Book and the polytheists will be in the Fire of Hell, to stay there forever. They are the worst of ˹all˺ beings','बेशक अहले किताब और मुशरेकीन से जो लोग (अब तक) काफ़िर हैं वह दोज़ख़ की आग में (होंगे) हमेशा उसी में रहेंगे यही लोग बदतरीन ख़लाएक़ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,7,'Al-Bayyina','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ','(اور) جو لوگ ایمان لائے اور نیک عمل کرتے رہے وہ تمام خلقت سے بہتر ہیں','Indeed, those who believe and do good—they are the best of ˹all˺ beings','बेशक जो लोग ईमान लाए और अच्छे काम करते रहे यही लोग बेहतरीन ख़लाएक़ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (98,8,'Al-Bayyina','جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدࣰ اۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ','ان کا صلہ ان کے پروردگار کے ہاں ہمیشہ رہنے کے باغ ہیں جن کے نیچے نہریں بہہ رہی ہیں ابدالاباد ان میں رہیں گے۔ خدا ان سے خوش اور وہ اس سے خوش۔ یہ (صلہ) اس کے لیے ہے جو اپنے پروردگار سے ڈرتا رہا','Their reward with their Lord will be Gardens of Eternity, under which rivers flow, to stay there for ever and ever. Allah is pleased with them and they are pleased with Him. This is ˹only˺ for those in awe of their Lord','उनकी जज़ा उनके परवरदिगार के यहाँ हमेशा रहने (सहने) के बाग़ हैं जिनके नीचे नहरें जारी हैं और वह आबादुल आबाद हमेशा उसी में रहेंगे ख़ुदा उनसे राज़ी और वह ख़ुदा से ख़ुश ये (जज़ा) ख़ास उस शख़्श की है जो अपने परवरदिगार से डरे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,1,'Az-Zalzala','إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا','جب زمین بھونچال سے ہلا دی جائے گی','When the earth is shaken ˹in˺ its ultimate quaking','जब ज़मीन बड़े ज़ोरों के साथ ज़लज़ले में आ जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,2,'Az-Zalzala','وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا','اور زمین اپنے (اندر) کے بوجھ نکال ڈالے گی','and when the earth throws out ˹all˺ its contents','और ज़मीन अपने अन्दर के बोझे (मादनयात मुर्दे वग़ैरह) निकाल डालेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,3,'Az-Zalzala','وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا','اور انسان کہے گا کہ اس کو کیا ہوا ہے؟','and humanity cries, “What is wrong with it?”—','और एक इन्सान कहेगा कि उसको क्या हो गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,4,'Az-Zalzala','يَوۡمَئِذࣲ تُحَدِّثُ أَخۡبَارَهَا','اس روز وہ اپنے حالات بیان کردے گی','on that Day the earth will recount everything','उस रोज़ वह अपने सब हालात बयान कर देगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,5,'Az-Zalzala','بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا','کیونکہ تمہارے پروردگار نے اس کو حکم بھیجا (ہوگا)','having been inspired by your Lord ˹to do so˺','क्योंकि तुम्हारे परवरदिगार ने उसको हुक्म दिया होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,6,'Az-Zalzala','يَوۡمَئِذࣲ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتࣰ ا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ','اس دن لوگ گروہ گروہ ہو کر آئیں گے تاکہ ان کو ان کے اعمال دکھا دیئے جائیں','On that Day people will proceed in separate groups to be shown ˹the consequences of˺ their deeds','उस दिन लोग गिरोह गिरोह (अपनी कब्रों से) निकलेंगे ताकि अपने आमाल को देखे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,7,'Az-Zalzala','فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرࣰ ا يَرَهُۥ','تو جس نے ذرہ بھر نیکی کی ہو گی وہ اس کو دیکھ لے گا','So whoever does an atom’s weight of good will see it','तो जिस शख्स ने ज़र्रा बराबर नेकी की वह उसे देख लेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (99,8,'Az-Zalzala','وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةࣲ شَرࣰّ ا يَرَهُۥ','اور جس نے ذرہ بھر برائی کی ہوگی وہ اسے دیکھ لے گا','And whoever does an atom’s weight of evil will see it','और जिस शख्स ने ज़र्रा बराबर बदी की है तो उसे देख लेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,1,'Al-Aadiyaat','وَٱلۡعَٰدِيَٰتِ ضَبۡحࣰ ا','ان سرپٹ دوڑنے والے گھوڑوں کی قسم جو ہانپ اٹھتےہیں','’ By the galloping, panting horses','(ग़ाज़ियों के) सरपट दौड़ने वाले घोड़ो की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,2,'Al-Aadiyaat','فَٱلۡمُورِيَٰتِ قَدۡحࣰ ا','پھر (پتھروں پر نعل) مار کر آگ نکالتے ہیں','striking sparks of fire ˹with their hoofs˺','जो नथनों से फ़रराटे लेते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,3,'Al-Aadiyaat','فَٱلۡمُغِيرَٰتِ صُبۡحࣰ ا','پھر صبح کو چھاپہ مارتے ہیں','launching raids at dawn','फिर पत्थर पर टाप मारकर चिंगारियाँ निकालते हैं फिर सुबह को छापा मारते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,4,'Al-Aadiyaat','فَأَثَرۡنَ بِهِۦ نَقۡعࣰ ا','پھر اس میں گرد اٹھاتے ہیں','stirring up ˹clouds of˺ dust','(तो दौड़ धूप से) बुलन्द कर देते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,5,'Al-Aadiyaat','فَوَسَطۡنَ بِهِۦ جَمۡعًا','پھر اس وقت دشمن کی فوج میں جا گھستے ہیں','and penetrating into the heart of enemy lines','फिर उस वक्त (दुश्मन के) दिल में घुस जाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,6,'Al-Aadiyaat','إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودࣱ‏','کہ انسان اپنے پروردگار کا احسان ناشناس (اور ناشکرا) ہے','Surely humankind is ungrateful to their Lord—','(ग़रज़ क़सम है) कि बेशक इन्सान अपने परवरदिगार का नाशुक्रा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,7,'Al-Aadiyaat','وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدࣱ‏','اور وہ اس سے آگاہ بھی ہے','and they certainly attest to this—','और यक़ीनी ख़ुदा भी उससे वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,8,'Al-Aadiyaat','وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ','وہ تو مال سے سخت محبت کرنے والا ہے','and they are truly extreme in their love of ˹worldly˺ gains','और बेशक वह माल का सख्त हरीस है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,9,'Al-Aadiyaat','۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ','کیا وہ اس وقت کو نہیں جانتا کہ جو (مردے) قبروں میں ہیں وہ باہر نکال لیے جائیں گے','Do they not know that when the contents of the graves will be spilled out','तो क्या वह ये नहीं जानता कि जब मुर्दे क़ब्रों से निकाले जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,10,'Al-Aadiyaat','وَحُصِّلَ مَا فِي ٱلصُّدُورِ','اور جو (بھید) دلوں میں ہیں وہ ظاہر کر دیئے جائیں گے','and the secrets of the hearts will be laid bare—','और दिलों के भेद ज़ाहिर कर दिए जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (100,11,'Al-Aadiyaat','إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذࣲ لَّخَبِيرُۢ','بےشک ان کا پروردگار اس روز ان سے خوب واقف ہوگا','surely their Lord is All-Aware of them on that Day','बेशक उस दिन उनका परवरदिगार उनसे ख़ूब वाक़िफ़ होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,1,'Al-Qaari''a','ٱلۡقَارِعَةُ','کھڑ کھڑانے والی','The Striking Disaster','खड़खड़ाने वाली');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,2,'Al-Qaari''a','مَا ٱلۡقَارِعَةُ','کھڑ کھڑانے والی کیا ہے؟','What is the Striking Disaster','वह खड़खड़ाने वाली क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,3,'Al-Qaari''a','وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ','اور تم کیا جانوں کھڑ کھڑانے والی کیا ہے؟','And what will make you realize what the Striking Disaster is','और तुम को क्या मालूम कि वह खड़खड़ाने वाली क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,4,'Al-Qaari''a','يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ','(وہ قیامت ہے) جس دن لوگ ایسے ہوں گے جیسے بکھرے ہوئے پتنگے','˹It is˺ the Day people will be like scattered moths','जिस दिन लोग (मैदाने हश्र में) टिड्डियों की तरह फैले होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,5,'Al-Qaari''a','وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ','اور پہاڑ ایسے ہو جائیں گے جیسے دھنکی ہوئی رنگ برنگ کی اون','and the mountains will be like carded wool','और पहाड़ धुनकी हुई रूई के से हो जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,6,'Al-Qaari''a','فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ','تو جس کے (اعمال کے) وزن بھاری نکلیں گے','So as for those whose scale is heavy ˹with good deeds˺','तो जिसके (नेक आमाल) के पल्ले भारी होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,7,'Al-Qaari''a','فَهُوَ فِي عِيشَةࣲ رَّاضِيَةࣲ‏','وہ دل پسند عیش میں ہو گا','they will be in a life of bliss','वह मन भाते ऐश में होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,8,'Al-Qaari''a','وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ','اور جس کے وزن ہلکے نکلیں گے','And as for those whose scale is light','और जिनके आमाल के पल्ले हल्के होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,9,'Al-Qaari''a','فَأُمُّهُۥ هَاوِيَةࣱ‏','اس کا مرجع ہاویہ ہے','their home will be the abyss','तो उनका ठिकाना न रहा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,10,'Al-Qaari''a','وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ','اور تم کیا سمجھے کہ ہاویہ کیا چیز ہے؟','And what will make you realize what that is','और तुमको क्या मालूम हाविया क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (101,11,'Al-Qaari''a','نَارٌ حَامِيَةُۢ','دہکتی ہوئی آگ ہے','˹It is˺ a scorching Fire','वह दहकती हुई आग है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,1,'At-Takaathur','أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ','(لوگو) تم کو (مال کی) بہت سی طلب نے غافل کر دیا','Competition for more ˹gains˺ diverts you ˹from Allah˺','कुल व माल की बहुतायत ने तुम लोगों को ग़ाफ़िल रखा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,2,'At-Takaathur','حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ','یہاں تک کہ تم نے قبریں جا دیکھیں','until you end up in ˹your˺ graves','यहाँ तक कि तुम लोगों ने कब्रें देखी (मर गए)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,3,'At-Takaathur','كَلَّا سَوۡفَ تَعۡلَمُونَ','دیکھو تمہیں عنقریب معلوم ہو جائے گا','But no! You will soon come to know','देखो तुमको अनक़रीब ही मालुम हो जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,4,'At-Takaathur','ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ','پھر دیکھو تمہیں عنقریب معلوم ہو جائے گا','Again, no! You will soon come to know','फिर देखो तुम्हें अनक़रीब ही मालूम हो जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,5,'At-Takaathur','كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ','دیکھو اگر تم جانتے (یعنی) علم الیقین (رکھتے تو غفلت نہ کرتے)','Indeed, if you were to know ˹your fate˺ with certainty, ˹you would have acted differently˺','देखो अगर तुमको यक़ीनी तौर पर मालूम होता (तो हरगिज़ ग़ाफिल न होते)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,6,'At-Takaathur','لَتَرَوُنَّ ٱلۡجَحِيمَ','تم ضرور دوزخ کو دیکھو گے','˹But˺ you will surely see the Hellfire','तुम लोग ज़रूर दोज़ख़ को देखोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,7,'At-Takaathur','ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ','پھر اس کو (ایسا) دیکھو گے (کہ) عین الیقین (آ جائے گا)','Again, you will surely see it with the eye of certainty','फिर तुम लोग यक़ीनी देखना देखोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (102,8,'At-Takaathur','ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ','پھر اس روز تم سے (شکر) نعمت کے بارے میں پرسش ہو گی','Then, on that Day, you will definitely be questioned about ˹your worldly˺ pleasures','फिर तुमसे नेअमतों के बारें ज़रूर बाज़ पुर्स की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (103,1,'Al-Asr','وَٱلۡعَصۡرِ','عصر کی قسم','By the ˹passage of˺ time','नमाज़े अस्र की क़सम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (103,2,'Al-Asr','إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ','کہ انسان نقصان میں ہے','Surely humanity is in ˹grave˺ loss','बेशक इन्सान घाटे में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (103,3,'Al-Asr','إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ','مگر وہ لوگ جو ایمان لائے اور نیک عمل کرتے رہے اور آپس میں حق (بات) کی تلقین اور صبر کی تاکید کرتے رہے','except those who have faith, do good, and urge each other to the truth, and urge each other to perseverance','मगर जो लोग ईमान लाए, और अच्छे काम करते रहे और आपस में हक़ का हुक्म और सब्र की वसीयत करते रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,1,'Al-Humaza','وَيۡلࣱ لِّكُلِّ هُمَزَةࣲ لُّمَزَةٍ','ہر طعن آمیز اشارتیں کرنے والے چغل خور کی خرابی ہے','Woe to every backbiter, slanderer','हर ताना देने वाले चुग़लख़ोर की ख़राबी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,2,'Al-Humaza','ٱلَّذِي جَمَعَ مَالࣰ ا وَعَدَّدَهُۥ','جو مال جمع کرتا اور اس کو گن گن کر رکھتا ہے','who amasses wealth ˹greedily˺ and counts it ˹repeatedly˺','जो माल को जमा करता है और गिन गिन कर रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,3,'Al-Humaza','يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ','(اور) خیال کرتا ہے کہ اس کا مال اس کی ہمیشہ کی زندگی کا موجب ہو گا','thinking that their wealth will make them immortal','वह समझता है कि उसका माल उसे हमेशा ज़िन्दा बाक़ी रखेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,4,'Al-Humaza','كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ','ہر گز نہیں وہ ضرور حطمہ میں ڈالا جائے گا','Not at all! Such a person will certainly be tossed into the Crusher','हरगिज़ नहीं वह तो ज़रूर हुतमा में डाला जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,5,'Al-Humaza','وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ','اور تم کیا سمجھے حطمہ کیا ہے؟','And what will make you realize what the Crusher is','और तुमको क्या मालूम हतमा क्या है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,6,'Al-Humaza','نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ','وہ خدا کی بھڑکائی ہوئی آگ ہے','˹It is˺ Allah’s kindled Fire','वह ख़ुदा की भड़काई हुई आग है जो (तलवे से लगी तो) दिलों तक चढ़ जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,7,'Al-Humaza','ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ','جو دلوں پر جا لپٹے گی','which rages over the hearts','ये लोग आग के लम्बे सुतूनो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,8,'Al-Humaza','إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةࣱ‏','(اور) وہ اس میں بند کر دیئے جائیں گے','It will be sealed over them','में डाल कर बन्द कर दिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (104,9,'Al-Humaza','فِي عَمَدࣲ مُّمَدَّدَةِۭ','(یعنی آگ کے) لمبے لمبے ستونوں میں','˹tightly secured˺ with long braces','जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (105,1,'Al-Fil','أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ','کیا تم نے نہیں دیکھا کہ تمہارے پروردگار نے ہاتھی والوں کے ساتھ کیا کیا','Have you not seen ˹O Prophet˺ how your Lord dealt with the Army of the Elephant','ऐ रसूल क्या तुमने नहीं देखा कि तुम्हारे परवरदिगार ने हाथी वालों के साथ क्या किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (105,2,'Al-Fil','أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلࣲ‏','کیا ان کا داؤں غلط نہیں کیا؟ (گیا)','Did He not frustrate their scheme','क्या उसने उनकी तमाम तद्बीरें ग़लत नहीं कर दीं (ज़रूर)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (105,3,'Al-Fil','وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ','اور ان پر جھلڑ کے جھلڑ جانور بھیجے','For He sent against them flocks of birds','और उन पर झुन्ड की झुन्ड चिड़ियाँ भेज दीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (105,4,'Al-Fil','تَرۡمِيهِم بِحِجَارَةࣲ مِّن سِجِّيلࣲ‏','جو ان پر کھنگر کی پتھریاں پھینکتے تھے','that pelted them with stones of baked clay','जो उन पर खरन्जों की कंकरियाँ फेकती थीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (105,5,'Al-Fil','فَجَعَلَهُمۡ كَعَصۡفࣲ مَّأۡكُولِۭ','تو ان کو ایسا کر دیا جیسے کھایا ہوا بھس','leaving them like chewed up straw','तो उन्हें चबाए हुए भूस की (तबाह) कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (106,1,'Quraish','لِإِيلَٰفِ قُرَيۡشٍ','قریش کے مانوس کرنے کے سبب','˹At least˺ for ˹the favour of˺ making Quraysh habitually secure—','चूँकि क़ुरैश को जाड़े और गर्मी के सफ़र से मानूस कर दिया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (106,2,'Quraish','إِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ','(یعنی) ان کو جاڑے اور گرمی کے سفر سے مانوس کرنے کے سبب','secure in their trading caravan ˹to Yemen˺ in the winter and ˹Syria˺ in the summer—','तो उनको मानूस कर देने की वजह से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (106,3,'Quraish','فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ','لوگوں کو چاہیئے کہ (اس نعمت کے شکر میں) اس گھر کے مالک کی عبادت کریں','let them worship the Lord of this ˹Sacred˺ House','इस घर (काबा) के मालिक की इबादत करनी चाहिए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (106,4,'Quraish','ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعࣲ وَءَامَنَهُم مِّنۡ خَوۡفِۭ','جس نے ان کو بھوک میں کھانا کھلایا اور خوف سے امن بخشا','Who has fed them against hunger and made them secure against fear','जिसने उनको भूख में खाना दिया और उनको खौफ़ से अमन अता किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,1,'Al-Maa''un','أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ','بھلا تم نے اس شخص کو دیکھا جو (روزِ) جزا کو جھٹلاتا ہے؟','Have you seen the one who denies the ˹final˺ Judgment','क्या तुमने उस शख़्श को भी देखा है जो रोज़ जज़ा को झुठलाता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,2,'Al-Maa''un','فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ','یہ وہی (بدبخت) ہے، جو یتیم کو دھکے دیتا ہے','That is the one who repulses the orphan','ये तो वही (कम्बख्त) है जो यतीम को धक्के देता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,3,'Al-Maa''un','وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ','اور فقیر کو کھانا کھلانے کے لیے (لوگوں کو) ترغیب نہیں دیتا','and does not encourage the feeding of the poor','और मोहताजों को खिलाने के लिए (लोगों को) आमादा नहीं करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,4,'Al-Maa''un','فَوَيۡلࣱ لِّلۡمُصَلِّينَ','تو ایسے نمازیوں کی خرابی ہے','So woe to those ˹hypocrites˺ who pray','तो उन नमाज़ियों की तबाही है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,5,'Al-Maa''un','ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ','جو نماز کی طرف سے غافل رہتے ہیں','yet are unmindful of their prayers','जो अपनी नमाज़ से ग़ाफिल रहते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,6,'Al-Maa''un','ٱلَّذِينَ هُمۡ يُرَآءُونَ','جو ریا کاری کرتے ہیں','those who ˹only˺ show off','जो दिखाने के वास्ते करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (107,7,'Al-Maa''un','وَيَمۡنَعُونَ ٱلۡمَاعُونَ','اور برتنے کی چیزیں عاریتہً نہیں دیتے','and refuse to give ˹even the simplest˺ aid','और रोज़मर्रा की मालूली चीज़ें भी आरियत नहीं देते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (108,1,'Al-Kawthar','إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ','(اے محمدﷺ) ہم نے تم کو کوثر عطا فرمائی ہے','Indeed, We have granted you ˹O Prophet˺ abundant goodness','(ऐ रसूल) हमनें तुमको को कौसर अता किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (108,2,'Al-Kawthar','فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ','تو اپنے پروردگار کے لیے نماز پڑھا کرو اور قربانی دیا کرو','So pray and sacrifice to your Lord ˹alone˺','तो तुम अपने परवरदिगार की नमाज़ पढ़ा करो');
